function loadSave() {
  try {
    const raw = JSON.parse(localStorage.getItem(SAVE_KEY) || "null");
    if (raw && typeof raw === "object") {
      raw.gold = Number.isFinite(raw.gold) ? raw.gold : 2500;
      raw.unlockedChars = Array.isArray(raw.unlockedChars) ? raw.unlockedChars : [1, 4, 7, 152, 155, 158, 252, 255, 258];
      raw.powerups = raw.powerups || {};
      raw.selectedChar = raw.selectedChar || 1;
      raw.selectedStage = raw.selectedStage || "forest";
      raw.localSeconds = raw.localSeconds || 0;
      return raw;
    }
  } catch (e) {}
  return {
    gold: 2500,
    unlockedChars: [1, 4, 7, 152, 155, 158, 252, 255, 258],
    powerups: {},
    selectedChar: 1,
    selectedStage: "forest",
    localSeconds: 0,
    bestKills: 0
  };
}
let SAVE = loadSave();
function writeSave() {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(SAVE)); } catch (e) {}
}

setInterval(() => {
  SAVE.localSeconds = (SAVE.localSeconds || 0) + 1;
  if (SAVE.localSeconds % 30 === 0) {
    SAVE.gold += 50;
    writeSave();
    const el = document.getElementById("menu-gold");
    if (el) el.textContent = SAVE.gold;
  }
}, 1000);

function getTypeEffectiveness(moveType, defTypes) {
  const atkIdx = TYPE_LIST.indexOf(moveType);
  if (atkIdx < 0 || !defTypes) return 1.0;
  let mul = 1.0;
  for (const dt of defTypes) {
    const defIdx = TYPE_LIST.indexOf(dt);
    if (defIdx >= 0) {
      const val = TYPE_CHART[atkIdx][defIdx];
      mul *= (val === 0 ? 0.35 : val);
    }
  }
  return mul;
}

function computePokemonStats(speciesId, level, isPlayer = false, isBoss = false) {
  const entry = POKE_DB[speciesId] || { t: ["normal"], s: [60, 60, 60, 60, 60, 60], bst: 360 };
  const [bHp, bAtk, bDef, bSpa, bSpd, bSpe] = entry.s;
  const pu = isPlayer ? (SAVE.powerups || {}) : {};

  const coreHp = Math.floor(((2 * bHp + 31) * level) / 100) + level + 10;
  let maxHp = coreHp;
  if (isPlayer) {
    maxHp = Math.floor((coreHp * 2.4 + 45) * (1 + (pu.hp || 0) * 0.03));
  } else if (isBoss) {
    maxHp = Math.floor(coreHp * 13.5 + 170);
  } else {
    maxHp = Math.floor(coreHp * 1.15 + 6);
  }

  const statFn = (base, evKey) => {
    const raw = Math.floor(((2 * base + 31) * level) / 100) + 8;
    return isPlayer ? Math.floor(raw * (1 + (pu[evKey] || 0) * 0.03)) : raw;
  };

  return {
    types: entry.t,
    bst: entry.bst,
    maxHp,
    atk: statFn(bAtk, "atk"),
    def: statFn(bDef, "def"),
    spa: statFn(bSpa, "spa"),
    spd: statFn(bSpd, "spd"),
    spe: statFn(bSpe, "spe")
  };
}

function computeMoveCooldown(moveId, attackerStats) {
  const m = MOVES_DB[moveId];
  if (!m) return 1.2;
  const effPower = m.p * (m.h > 1 ? (m.h > 2 ? 2.4 : 1.7) : 1.0);
  // Distinct cadence per mechanic archetype!
  let baseCd = 0.65 + Math.pow(effPower / 40, 0.70) * 0.42;
  if (m.pat === "vs_bible") baseCd = 2.6;       // Orbiting blades last 2.2s, re-cast every ~2.3s
  else if (m.pat === "vs_santa") baseCd = 2.2;  // Ground hazard pools last 3.2s
  else if (m.pat === "vs_garlic") baseCd = 0.85;// Rapid pulsing aura ring
  else if (m.pat === "br_thrust") baseCd *= 0.82; // Snappy Brotato melee thrusts
  const speFactor = Math.max(0.62, Math.min(1.15, 110 / (85 + attackerStats.spe * 0.45)));
  return Math.max(0.42, baseCd * speFactor);
}

function calculatePokemonDamage(attackerLv, attackerStats, moveId, defenderLv, defenderStats, aoeScale = 1.0) {
  const m = MOVES_DB[moveId];
  if (!m) return { dmg: 5, eff: 1.0, isCrit: false, stab: 1.0 };

  const isPhys = m.c === "physical";
  let A = isPhys ? attackerStats.atk : attackerStats.spa;
  const D = Math.max(1, isPhys ? defenderStats.def : defenderStats.spd);

  const stab = attackerStats.types.includes(m.t) ? 1.5 : 1.0;
  const eff = getTypeEffectiveness(m.t, defenderStats.types);
  const isCrit = Math.random() * 100 < (m.cr || 6);
  const critMul = isCrit ? 1.5 : 1.0;
  const randVar = 0.90 + Math.random() * 0.15;

  const baseDmg = (((2 * attackerLv / 5 + 2) * m.p * (A / D)) / 50 + 2);
  const finalDmg = Math.max(1, Math.round(baseDmg * stab * eff * critMul * aoeScale * randVar));
  return { dmg: finalDmg, eff, isCrit, stab };
}

const IMG_CACHE = new Map();
function getImg(src) {
  if (IMG_CACHE.has(src)) return IMG_CACHE.get(src);
  const img = new Image();
  img.src = src;
  IMG_CACHE.set(src, img);
  return img;
}

let bgmAudio = null;
function playBgm(src) {
  try {
    if (bgmAudio) { bgmAudio.pause(); bgmAudio = null; }
    bgmAudio = new Audio(src);
    bgmAudio.loop = true;
    bgmAudio.volume = 0.40;
    bgmAudio.play().catch(() => {});
  } catch (e) {}
}
function playCry(pid) {
  try {
    const a = new Audio(`./assets/cries/${pid}.ogg`);
    a.volume = 0.45;
    a.play().catch(() => {});
  } catch (e) {}
}

let audioCtx = null;
function sfx(type) {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === "suspended") audioCtx.resume();
    const now = audioCtx.currentTime;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    if (type === "gem") {
      osc.type = "sine";
      osc.frequency.setValueAtTime(680 + Math.random() * 220, now);
      osc.frequency.exponentialRampToValueAtTime(1150, now + 0.06);
      gain.gain.setValueAtTime(0.07, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.065);
      osc.start(now); osc.stop(now + 0.07);
    } else if (type === "hit") {
      osc.type = "triangle";
      osc.frequency.setValueAtTime(165, now);
      osc.frequency.linearRampToValueAtTime(65, now + 0.05);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.05);
      osc.start(now); osc.stop(now + 0.055);
    } else if (type === "level") {
      osc.type = "square";
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(554, now + 0.07);
      osc.frequency.setValueAtTime(659, now + 0.14);
      osc.frequency.setValueAtTime(880, now + 0.21);
      gain.gain.setValueAtTime(0.10, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.35);
      osc.start(now); osc.stop(now + 0.36);
    } else if (type === "chest") {
      osc.type = "triangle";
      osc.frequency.setValueAtTime(523, now);
      osc.frequency.setValueAtTime(659, now + 0.08);
      osc.frequency.setValueAtTime(784, now + 0.16);
      osc.frequency.setValueAtTime(1046, now + 0.24);
      gain.gain.setValueAtTime(0.14, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.48);
      osc.start(now); osc.stop(now + 0.5);
    }
  } catch (e) {}
}

function drawPokemonSprite(ctx, pid, x, y, vx, vy, animTime, scale = 1.6, flashWhite = false, ringColor = null, hopY = 0) {
  const img = getImg(`./assets/pmd/${pid}.png`);
  const meta = SPRITE_META[pid] || [0, 32, 32, 4];
  const [wy, fw, fh, fn] = meta;
  if (!img.complete || img.naturalWidth === 0) {
    const iconImg = getImg(`./assets/portraits/${pid}.png`);
    if (iconImg.complete && iconImg.naturalWidth > 0) {
      const sz = 36 * scale;
      ctx.drawImage(iconImg, x - sz / 2, y - sz / 2 - hopY, sz, sz);
    }
    return;
  }
  let row = 0;
  if (Math.abs(vx) > 0.01 || Math.abs(vy) > 0.01) {
    const ang = Math.atan2(vx, vy);
    row = (Math.round(ang / (Math.PI / 4)) % 8 + 8) % 8;
  }
  const col = Math.floor(animTime * 8) % Math.max(1, fn);
  const sx = col * fw;
  const sy = wy + row * fh;
  const dw = fw * scale;
  const dh = fh * scale;

  ctx.fillStyle = "rgba(0, 0, 0, 0.36)";
  ctx.beginPath();
  ctx.ellipse(x, y + dh * 0.34, dw * 0.32, dh * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();

  if (ringColor) {
    ctx.strokeStyle = ringColor;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.ellipse(x, y + dh * 0.34, dw * 0.42, dh * 0.19, 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  ctx.save();
  if (flashWhite) ctx.filter = "brightness(2.8) contrast(1.5)";
  ctx.drawImage(img, sx, sy, fw, fh, x - dw / 2, y - dh / 2 - hopY, dw, dh);
  ctx.restore();
}

