function getStartingMoves(starterId) {
  const ls = STARTER_LEARNSETS[starterId]?.levelMoves || [];
  const lv1 = ls.filter(x => x[1] <= 1).map(x => x[0]);
  return lv1.slice(0, 2);
}

function renderMenu() {
  document.getElementById("menu-gold").textContent = SAVE.gold;
  document.getElementById("char-count").textContent = `已解锁 ${SAVE.unlockedChars.length} / ${CHARACTERS.length}`;

  const grid = document.getElementById("char-grid");
  grid.innerHTML = "";
  for (const ch of CHARACTERS) {
    const unlocked = SAVE.unlockedChars.includes(ch.id);
    const active = SAVE.selectedChar === ch.id;
    const startMoves = getStartingMoves(ch.id).map(m => MOVES_DB[m]?.n).join(" / ");
    const card = document.createElement("div");
    card.className = "char-card" + (active ? " active" : "") + (unlocked ? "" : " locked");
    card.innerHTML = `
      <span style="position:absolute;top:3px;left:5px;font-size:9px;color:#b8a0d8;font-weight:900;">G${ch.gen}·${ch.region}</span>
      <img class="av" src="./assets/portraits/${ch.id}.png" alt="" />
      <div class="cname">${POKEMON_ZH[ch.id]}</div>
      <div class="cwep">${startMoves}</div>
      ${unlocked ? "" : `<div style="font-size:10px;color:#ffd54f;margin-top:2px;">🔒 ${ch.cost} 金币</div>`}
    `;
    card.onclick = () => {
      if (!unlocked) {
        if (SAVE.gold >= ch.cost) {
          SAVE.gold -= ch.cost;
          SAVE.unlockedChars.push(ch.id);
          SAVE.selectedChar = ch.id;
          writeSave();
          playCry(ch.id);
          renderMenu();
        } else {
          alert(`金币不足！需要 ${ch.cost} 金币。`);
        }
        return;
      }
      SAVE.selectedChar = ch.id;
      writeSave();
      playCry(ch.id);
      renderMenu();
    };
    grid.appendChild(card);
  }

  const curId = SAVE.selectedChar;
  const lsData = STARTER_LEARNSETS[curId];
  const s3 = POKE_DB[lsData.chain[2]];
  const typeBadges = s3.t.map(t => `<span style="background:${TYPE_META[t].color};color:#fff;padding:1px 6px;border-radius:3px;font-size:10px;font-weight:900;">${TYPE_ZH[t]}</span>`).join(" ");

  const evoChainHtml = lsData.chain.map((pid, idx) => `
    <div style="display:flex;flex-direction:column;align-items:center;">
      <img src="./assets/icons/${pid}.png" style="width:30px;height:30px;image-rendering:pixelated;" />
      <span style="font-size:10px;color:#ffe066;font-weight:800;">${POKEMON_ZH[pid]}</span>
      <span style="font-size:9px;color:#aaa;">${idx === 0 ? "Lv.1(BST:" + POKE_DB[pid].bst + ")" : idx === 1 ? "Lv." + lsData.evoLevels[0] + "(BST:" + POKE_DB[pid].bst + ")" : "Lv." + lsData.evoLevels[1] + "(BST:" + POKE_DB[pid].bst + ")"}</span>
    </div>
  `).join(`<span style="color:#ffd54f;font-weight:900;">→</span>`);

  const lvMovePreview = lsData.levelMoves.slice(0, 6).map(([mid, lv]) => `Lv.${lv} ${MOVES_DB[mid]?.n}`).join(" · ");

  document.getElementById("char-detail").innerHTML = `
    <img src="./assets/portraits/${curId}.png" style="width:64px;height:64px;image-rendering:pixelated;border:2px solid #d4af37;border-radius:6px;background:#120b1c;" />
    <div style="flex:1;">
      <div style="display:flex;justify-content:space-between;align-items:center;">
        <b style="font-size:16px;color:#ffe066;">${POKEMON_ZH[curId]} ${typeBadges}</b>
        <span style="font-size:10px;color:#82e0aa;">最终形态种族值：HP ${s3.s[0]}/物攻 ${s3.s[1]}/物防 ${s3.s[2]}/特攻 ${s3.s[3]}/特防 ${s3.s[4]}/速度 ${s3.s[5]}</span>
      </div>
      <div style="font-size:10px;color:#90caf9;margin:3px 0;">升级招式：${lvMovePreview} 等 (含12大机制共 ${lsData.tmMoves.length} 种专属合法TM)</div>
      <div style="display:flex;align-items:center;justify-content:space-between;background:#150e20;padding:3px 8px;border-radius:5px;">
        <span style="font-size:10px;color:#cbb98b;">原版进化等级与种族值：</span>
        <div style="display:flex;align-items:center;gap:4px;">${evoChainHtml}</div>
      </div>
    </div>
  `;

  const stList = document.getElementById("stage-list");
  stList.innerHTML = "";
  for (const st of STAGES) {
    const active = SAVE.selectedStage === st.id;
    const item = document.createElement("div");
    item.style.cssText = `padding:7px 10px;border-radius:5px;border:2px solid ${active ? "#ffe066" : "#5e4724"};background:${active ? "#38234d" : "#1a1126"};cursor:pointer;display:flex;justify-content:space-between;align-items:center;`;
    item.innerHTML = `
      <div>
        <div style="font-weight:900;font-size:13px;color:${active ? "#ffe066" : "#fff"};">${st.name}</div>
        <div style="font-size:10px;color:#c9b896;margin-top:2px;">${st.desc}</div>
      </div>
      <span style="font-size:11px;font-weight:900;color:#ffd54f;flex-shrink:0;margin-left:8px;">🪙 ×${st.goldMul}</span>
    `;
    item.onclick = () => {
      SAVE.selectedStage = st.id;
      writeSave();
      renderMenu();
    };
    stList.appendChild(item);
  }
}

function showPowerupsModal() {
  const ov = document.getElementById("modal-ov");
  const box = document.getElementById("modal-box");
  ov.style.display = "flex";
  function draw() {
    let rowsHtml = "";
    for (const p of POWERUPS) {
      const lv = SAVE.powerups[p.id] || 0;
      const cost = Math.round(p.baseCost * Math.pow(1.5, lv));
      const maxed = lv >= p.max;
      rowsHtml += `
        <div style="background:#1c1229;border:2px solid ${maxed ? "#4caf50" : "#785c28"};border-radius:6px;padding:8px;display:flex;align-items:center;gap:10px;">
          <img src="${p.icon}" style="width:32px;height:32px;image-rendering:pixelated;" />
          <div style="flex:1;">
            <div style="font-weight:900;font-size:13px;color:#ffe066;">${p.name} <span style="color:#fff;">Lv.${lv}/${p.max}</span></div>
            <div style="font-size:11px;color:#ccc;margin-top:2px;">${p.desc}</div>
          </div>
          ${maxed
            ? `<span style="color:#69f0ae;font-weight:900;font-size:12px;">已满</span>`
            : `<button class="vs-btn gold" data-buy="${p.id}" style="padding:5px 10px;font-size:12px;">🪙 ${cost}</button>`}
        </div>
      `;
    }
    box.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
        <b style="font-size:18px;color:#ffe066;">⚡ 宝可梦六维努力值特训 (EV Training)</b>
        <div style="display:flex;gap:8px;align-items:center;">
          <span style="color:#ffd54f;font-weight:900;">🪙 ${SAVE.gold}</span>
          <button id="close-modal" class="vs-btn" style="padding:4px 10px;font-size:12px;">关闭</button>
        </div>
      </div>
      <p style="font-size:11px;color:#cbb98b;margin-bottom:8px;">为保持严格的战斗数值平衡，局外努力值上限控制在 +15% 以内，核心战力取决于宝可梦等级、种族值进化与招式机制搭配。</p>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:8px;">${rowsHtml}</div>
    `;
    box.querySelector("#close-modal").onclick = () => { ov.style.display = "none"; renderMenu(); };
    box.querySelectorAll("[data-buy]").forEach(btn => {
      btn.onclick = () => {
        const pid = btn.getAttribute("data-buy");
        const p = POWERUPS.find(x => x.id === pid);
        const lv = SAVE.powerups[pid] || 0;
        const cost = Math.round(p.baseCost * Math.pow(1.5, lv));
        if (lv < p.max && SAVE.gold >= cost) {
          SAVE.gold -= cost;
          SAVE.powerups[pid] = lv + 1;
          writeSave();
          sfx("level");
          draw();
        } else {
          alert("金币不足！");
        }
      };
    });
  }
  draw();
}

