// ============================================================================
// 360° Silky Floating Follow Joystick (Zero WebView Gesture Interception!)
// ============================================================================
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

let RUN = null;
const KEYS = new Set();
window.addEventListener("keydown", e => {
  KEYS.add(e.code);
  if (e.code === "Escape" && RUN && !RUN.over) {
    if (RUN.paused && !RUN.modalOpen) resumeRun();
    else if (!RUN.paused) pauseRun();
  }
});
window.addEventListener("keyup", e => KEYS.delete(e.code));

// Floating Joystick State: base (sx, sy) dynamically follows thumb when thumb exceeds maxR (48px),
// so reversing or rotating direction 360° is instant with zero re-tapping!
const JOY = { active: false, id: null, sx: 0, sy: 0, cx: 0, cy: 0, dx: 0, dy: 0, dist: 0, maxR: 48 };

function updateJoystickFromPoint(clientX, clientY) {
  JOY.cx = clientX;
  JOY.cy = clientY;
  let rx = JOY.cx - JOY.sx;
  let ry = JOY.cy - JOY.sy;
  let dist = Math.hypot(rx, ry);

  // Dynamic floating base: if thumb drags past maxR, pull base along smoothly so turning back is immediate!
  if (dist > JOY.maxR) {
    const ux = rx / dist;
    const uy = ry / dist;
    JOY.sx = JOY.cx - ux * JOY.maxR;
    JOY.sy = JOY.cy - uy * JOY.maxR;
    rx = JOY.cx - JOY.sx;
    ry = JOY.cy - JOY.sy;
    dist = JOY.maxR;
  }

  JOY.dist = dist;
  if (dist > 4) {
    JOY.dx = rx / dist;
    JOY.dy = ry / dist;
  } else {
    JOY.dx = 0;
    JOY.dy = 0;
  }
}

// Native Touch Events with { passive: false } & e.preventDefault() so Android WebView NEVER cancels drag!
canvas.addEventListener("touchstart", e => {
  if (!RUN || RUN.paused || RUN.over) return;
  e.preventDefault();
  if (!JOY.active && e.changedTouches.length > 0) {
    const t = e.changedTouches[0];
    JOY.active = true;
    JOY.id = t.identifier;
    JOY.sx = t.clientX;
    JOY.sy = t.clientY;
    JOY.cx = t.clientX;
    JOY.cy = t.clientY;
    JOY.dx = 0;
    JOY.dy = 0;
    JOY.dist = 0;
  }
}, { passive: false });

window.addEventListener("touchmove", e => {
  if (!JOY.active) return;
  for (let i = 0; i < e.changedTouches.length; i++) {
    const t = e.changedTouches[i];
    if (t.identifier === JOY.id) {
      e.preventDefault();
      updateJoystickFromPoint(t.clientX, t.clientY);
      break;
    }
  }
}, { passive: false });

function endTouchJoy(e) {
  if (!JOY.active) return;
  for (let i = 0; i < e.changedTouches.length; i++) {
    if (e.changedTouches[i].identifier === JOY.id) {
      JOY.active = false;
      JOY.id = null;
      JOY.dx = 0;
      JOY.dy = 0;
      JOY.dist = 0;
      break;
    }
  }
}
window.addEventListener("touchend", endTouchJoy, { passive: false });
window.addEventListener("touchcancel", endTouchJoy, { passive: false });

// Mouse fallback for desktop testing
canvas.addEventListener("mousedown", e => {
  if (!RUN || RUN.paused || RUN.over || JOY.active) return;
  JOY.active = true;
  JOY.id = "mouse";
  JOY.sx = e.clientX;
  JOY.sy = e.clientY;
  JOY.cx = e.clientX;
  JOY.cy = e.clientY;
  JOY.dx = 0;
  JOY.dy = 0;
});
window.addEventListener("mousemove", e => {
  if (JOY.active && JOY.id === "mouse") {
    updateJoystickFromPoint(e.clientX, e.clientY);
  }
});
window.addEventListener("mouseup", () => {
  if (JOY.active && JOY.id === "mouse") {
    JOY.active = false;
    JOY.id = null;
    JOY.dx = 0;
    JOY.dy = 0;
  }
});

function resizeCanvas() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  ctx.imageSmoothingEnabled = false;
}
window.addEventListener("resize", resizeCanvas);
resizeCanvas();

// ============================================================================
// Start Run & HUD Updates
// ============================================================================
function startRun() {
  const charDef = CHARACTERS.find(c => c.id === SAVE.selectedChar) || CHARACTERS[0];
  const stageDef = STAGES.find(s => s.id === SAVE.selectedStage) || STAGES[0];
  const lsData = STARTER_LEARNSETS[charDef.id];

  let wildPool = [];
  let bossPool = [];
  for (const g of stageDef.gens) {
    wildPool = wildPool.concat(GEN_WILDS[g] || []);
    bossPool = bossPool.concat(GEN_BOSSES[g] || []);
  }

  const initLv = 5;
  const pStats = computePokemonStats(charDef.id, initLv, true, false);
  const startMoveIds = getStartingMoves(charDef.id);

  RUN = {
    isPlayerUnit: true,
    baseId: charDef.id,
    speciesId: lsData.chain[0],
    evoStage: 0,
    stage: stageDef,
    wildPool,
    bossPool,
    level: initLv,
    xp: 0,
    xpNeed: 22,
    stats: pStats,
    hp: pStats.maxHp,
    maxHp: pStats.maxHp,
    x: 0,
    y: 0,
    vx: 0,
    vy: 1,
    facingX: 1,
    facingY: 0,
    dashT: 0,
    dashVx: 0,
    dashVy: 0,
    dashMoveId: 0,
    dashHitSet: new Set(),
    invulnT: 0,
    kills: 0,
    gold: 0,
    time: 0,
    paused: false,
    modalOpen: false,
    over: false,
    moves: startMoveIds.map(mid => ({ id: mid, timer: 0.2 })),
    learnedHistory: new Set(startMoveIds),
    companions: [],
    fieldTMs: [],
    fieldBalls: [],
    gems: [],
    enemies: [],
    // Distinct Combat Entities for the 12 VS / Brotato Mechanics:
    orbitals: [],     // vs_bible (King Bible orbiting blades/petals/flames)
    boomerangs: [],   // vs_cross (Cross boomerangs that fly out and return to owner)
    meleeSwings: [],  // br_thrust & vs_whip (Brotato extending thrusts/cleaves & VS horizontal whips)
    lasers: [],       // pk_laser (Continuous piercing beams)
    projectiles: [],  // vs_runetracer, vs_axe, vs_santa (in-flight flasks)
    zones: [],        // vs_santa pools, vs_garlic rings, vs_lightning pillars, pk_jaw snaps
    afterimages: [],  // pk_dash speed trails
    popups: [],
    modalQueue: [],
    spawnAcc: 0,
    tmSpawnAcc: 12,
    ballSpawnAcc: 16,
    bossAcc: 45,
    bossIndex: 0,
    activeBoss: null
  };

  document.getElementById("scr-menu").style.display = "none";
  document.getElementById("hud").style.display = "block";
  playBgm(stageDef.bgm);
  playCry(RUN.speciesId);
  spawnFieldTM(true);
  spawnCompanionBall(true);
  updateHudSlots();
}

function enqueueModal(fn) {
  if (!RUN) return;
  JOY.active = false; JOY.dx = 0; JOY.dy = 0;
  RUN.modalQueue.push(fn);
  processNextModal();
}

function processNextModal() {
  if (!RUN || RUN.over || RUN.modalOpen) return;
  if (RUN.modalQueue.length === 0) {
    RUN.paused = false;
    return;
  }
  const nextFn = RUN.modalQueue.shift();
  RUN.paused = true;
  RUN.modalOpen = true;
  nextFn();
}

function closeCurrentModal() {
  document.getElementById("modal-ov").style.display = "none";
  if (!RUN) return;
  RUN.modalOpen = false;
  processNextModal();
}

function updateHudSlots() {
  if (!RUN) return;
  const wepEl = document.getElementById("wep-slots");
  const pasEl = document.getElementById("pas-slots");
  wepEl.innerHTML = "";
  pasEl.innerHTML = "";

  for (let i = 0; i < 4; i++) {
    const mSlot = RUN.moves[i];
    const div = document.createElement("div");
    if (mSlot) {
      const m = MOVES_DB[mSlot.id];
      const tm = TYPE_META[m.t];
      const mechShort = m.mn.split("】")[0].replace("【", "");
      div.className = "move-slot";
      div.style.borderColor = tm.color;
      div.innerHTML = `
        <img src="${tm.icon}" />
        <div style="line-height:1.15;">
          <div style="font-size:11px;font-weight:900;color:#fff;">${m.n}</div>
          <div style="font-size:9px;color:#ffd54f;">${mechShort} · P:${m.p}</div>
        </div>
      `;
    } else {
      div.className = "move-slot empty";
      div.textContent = `招式槽 ${i + 1}`;
    }
    wepEl.appendChild(div);
  }

  for (let i = 0; i < 5; i++) {
    const comp = RUN.companions[i];
    const div = document.createElement("div");
    if (comp) {
      const m = MOVES_DB[comp.moveId];
      const tm = TYPE_META[m.t];
      div.className = "comp-slot";
      div.style.borderColor = tm.color;
      div.innerHTML = `
        <img src="./assets/icons/${comp.speciesId}.png" />
        <div style="line-height:1.15;">
          <div style="font-size:11px;font-weight:900;color:#81d4fa;">Lv.${comp.level} ${POKEMON_ZH[comp.speciesId]}</div>
          <div style="font-size:9px;color:#ffe066;">${m.n} (${m.mn.split("】")[0].replace("【", "")})</div>
        </div>
      `;
    } else {
      div.className = "comp-slot empty";
      div.textContent = `同伴槽 ${i + 1}`;
    }
    pasEl.appendChild(div);
  }

  const stEl = document.getElementById("hud-stats");
  if (stEl) {
    stEl.textContent = `HP ${Math.ceil(RUN.hp)}/${RUN.maxHp} · 物攻${RUN.stats.atk} 特攻${RUN.stats.spa} 防${RUN.stats.def}/${RUN.stats.spd} 速${RUN.stats.spe}`;
  }
}

function spawnFieldTM(near = false) {
  if (!RUN || RUN.fieldTMs.length >= 5) return;
  const lsData = STARTER_LEARNSETS[RUN.baseId];
  const equippedIds = new Set(RUN.moves.map(m => m.id));
  const maxPowerAllowed = RUN.level < 12 ? 65 : (RUN.level < 22 ? 90 : (RUN.level < 32 ? 115 : 999));
  let candidates = lsData.tmMoves.filter(mid => !equippedIds.has(mid) && MOVES_DB[mid] && MOVES_DB[mid].p <= maxPowerAllowed);
  if (candidates.length === 0) {
    candidates = lsData.tmMoves.filter(mid => !equippedIds.has(mid) && MOVES_DB[mid]);
  }
  if (candidates.length === 0) return;

  // Prefer giving a mechanic archetype the player doesn't currently have equipped!
  const currentPats = new Set(RUN.moves.map(m => MOVES_DB[m.id]?.pat));
  const diffPatCandidates = candidates.filter(mid => !currentPats.has(MOVES_DB[mid].pat));
  const pool = (diffPatCandidates.length > 0 && Math.random() < 0.78) ? diffPatCandidates : candidates;

  const moveId = pool[Math.floor(Math.random() * pool.length)];
  const ang = Math.random() * Math.PI * 2;
  const dist = near ? 115 : (210 + Math.random() * 200);
  RUN.fieldTMs.push({
    x: RUN.x + Math.cos(ang) * dist,
    y: RUN.y + Math.sin(ang) * dist,
    moveId
  });
}

function spawnCompanionBall(near = false, x = null, y = null) {
  if (!RUN || RUN.fieldBalls.length >= 4) return;
  const ang = Math.random() * Math.PI * 2;
  const dist = near ? 105 : (190 + Math.random() * 200);
  RUN.fieldBalls.push({
    x: x !== null ? x : RUN.x + Math.cos(ang) * dist,
    y: y !== null ? y : RUN.y + Math.sin(ang) * dist
  });
}

function offerPlayerMove(moveId, sourceLabel = "升级领悟") {
  if (!RUN) return;
  if (RUN.moves.some(m => m.id === moveId)) return;
  const newMove = MOVES_DB[moveId];
  if (!newMove) return;

  if (RUN.moves.length < 4) {
    RUN.moves.push({ id: moveId, timer: 0.2 });
    sfx("level");
    updateHudSlots();
    addPopup(RUN.x, RUN.y - 42, `💿 ${sourceLabel}：学会了【${newMove.n}】(${newMove.mn.split("】")[0]}】)！`, "#ffe066", 1.25);
    return;
  }

  enqueueModal(() => {
    const ov = document.getElementById("modal-ov");
    const box = document.getElementById("modal-box");
    ov.style.display = "flex";

    const newTm = TYPE_META[newMove.t];
    const newStab = RUN.stats.types.includes(newMove.t) ? 1.5 : 1.0;
    const newAtk = newMove.c === "physical" ? RUN.stats.atk : RUN.stats.spa;
    const newEstDmg = Math.round((((2 * RUN.level / 5 + 2) * newMove.p * (newAtk / 45)) / 50 + 2) * newStab);

    let slotsHtml = "";
    RUN.moves.forEach((mSlot, idx) => {
      const om = MOVES_DB[mSlot.id];
      const otm = TYPE_META[om.t];
      const oStab = RUN.stats.types.includes(om.t) ? 1.5 : 1.0;
      const oAtk = om.c === "physical" ? RUN.stats.atk : RUN.stats.spa;
      const oEstDmg = Math.round((((2 * RUN.level / 5 + 2) * om.p * (oAtk / 45)) / 50 + 2) * oStab);
      slotsHtml += `
        <button class="choice-btn" data-replace="${idx}">
          <div class="choice-ic"><img src="${otm.icon}" /></div>
          <div style="flex:1;">
            <div>
              <b style="font-size:15px;color:#fff;">遗忘【${om.n}】替换为【${newMove.n}】</b>
              <span class="choice-tag" style="background:${otm.color};color:#fff;">${TYPE_ZH[om.t]}·${om.c === "physical" ? "物理" : "特殊"}</span>
            </div>
            <div style="font-size:11px;color:#81d4fa;margin-top:2px;">原机制：${om.mn} (威力${om.p} · 预估≈${oEstDmg})</div>
          </div>
        </button>
      `;
    });

    box.innerHTML = `
      <div style="text-align:center;margin-bottom:8px;">
        <div style="font-size:20px;font-weight:900;color:#ffe066;">💿 ${sourceLabel}：想要学习【${newMove.n}】！</div>
        <div style="font-size:12px;color:#cbb98b;margin-top:2px;">【${POKEMON_ZH[RUN.speciesId]}】已带满 4 个招式，请选择要遗忘替换的招式：</div>
      </div>
      <div style="background:#160e24;border:2px solid ${newTm.color};border-radius:6px;padding:8px 12px;margin-bottom:8px;display:flex;align-items:center;gap:10px;">
        <img src="${newTm.icon}" style="width:32px;height:32px;image-rendering:pixelated;" />
        <div>
          <b style="font-size:15px;color:${newTm.color};">新招式：${newMove.n} [${TYPE_ZH[newMove.t]} · ${newMove.c === "physical" ? "物理" : "特殊"}]</b>
          <div style="font-size:12px;color:#81d4fa;font-weight:900;margin:2px 0;">攻击机制：${newMove.mn}</div>
          <div style="font-size:12px;color:#fff;">威力：<b>${newMove.p}${newMove.h > 1 ? "×" + newMove.h : ""}</b> · 本系加成：<b>${newStab > 1 ? "1.5×" : "1.0×"}</b> · 当前面板预估伤害：<b>≈${newEstDmg}</b></div>
        </div>
      </div>
      <div>${slotsHtml}</div>
      <button id="btn-skip-move" class="vs-btn" style="width:100%;margin-top:8px;">放弃学习【${newMove.n}】</button>
    `;

    box.querySelectorAll("[data-replace]").forEach(btn => {
      btn.onclick = () => {
        const idx = parseInt(btn.getAttribute("data-replace"), 10);
        const oldName = MOVES_DB[RUN.moves[idx].id].n;
        RUN.moves[idx] = { id: moveId, timer: 0.15 };
        sfx("level");
        updateHudSlots();
        addPopup(RUN.x, RUN.y - 45, `✨ 忘了【${oldName}】，学会了【${newMove.n}】！`, "#ffe066", 1.3);
        closeCurrentModal();
      };
    });
    box.querySelector("#btn-skip-move").onclick = () => {
      closeCurrentModal();
    };
  });
}

// ============================================================================
// Dynamic Autonomous Companion Pokemon Creation & Level-Up
// ============================================================================
function createCompanion(baseStarterId) {
  const lsData = STARTER_LEARNSETS[baseStarterId];
  const initLv = Math.max(4, Math.floor(RUN.level * 0.8));
  let evoStage = 0;
  if (initLv >= lsData.evoLevels[1]) evoStage = 2;
  else if (initLv >= lsData.evoLevels[0]) evoStage = 1;
  const speciesId = lsData.chain[evoStage];
  const stats = computePokemonStats(speciesId, initLv, false, false);

  let moveId = lsData.levelMoves[0][0];
  for (const [mid, reqLv] of lsData.levelMoves) {
    if (initLv >= reqLv) moveId = mid;
  }

  return {
    isPlayerUnit: false,
    baseId: baseStarterId,
    speciesId,
    evoStage,
    level: initLv,
    xp: 0,
    xpNeed: Math.round(14 + initLv * 7),
    stats,
    moveId,
    timer: 0.3,
    x: RUN.x + (Math.random() - 0.5) * 80,
    y: RUN.y + (Math.random() - 0.5) * 80,
    vx: 0,
    vy: 1,
    facingX: 1,
    facingY: 0,
    dashT: 0,
    dashVx: 0,
    dashVy: 0,
    dashMoveId: 0,
    dashHitSet: new Set(),
    lungeT: 0,
    lungeDx: 0,
    lungeDy: 0,
    calloutText: `上吧！${MOVES_DB[moveId].n}！`,
    calloutT: 2.0,
    patrolAng: Math.random() * Math.PI * 2,
    animOffset: Math.random() * 10
  };
}

function gainCompanionXp(comp, amount) {
  comp.xp += amount;
  while (comp.xp >= comp.xpNeed) {
    comp.xp -= comp.xpNeed;
    comp.level++;
    comp.xpNeed = Math.round(14 + comp.level * 8 + Math.pow(comp.level, 1.25) * 2);

    const lsData = STARTER_LEARNSETS[comp.baseId];
    let newEvoStage = comp.evoStage;
    if (comp.level >= lsData.evoLevels[1]) newEvoStage = 2;
    else if (comp.level >= lsData.evoLevels[0]) newEvoStage = 1;

    if (newEvoStage > comp.evoStage) {
      comp.evoStage = newEvoStage;
      comp.speciesId = lsData.chain[newEvoStage];
      playCry(comp.speciesId);
      addPopup(comp.x, comp.y - 38, `🌟 同伴进化为【${POKEMON_ZH[comp.speciesId]}】！`, "#81d4fa", 1.38);
    }

    comp.stats = computePokemonStats(comp.speciesId, comp.level, false, false);

    let bestMoveId = comp.moveId;
    for (const [mid, reqLv] of lsData.levelMoves) {
      if (comp.level === reqLv) bestMoveId = mid;
    }
    if (bestMoveId !== comp.moveId) {
      comp.moveId = bestMoveId;
      comp.calloutText = `领悟：${MOVES_DB[bestMoveId].n}！`;
      comp.calloutT = 2.4;
      addPopup(comp.x, comp.y - 24, `✨ 同伴【${POKEMON_ZH[comp.speciesId]}】Lv.${comp.level} 领悟【${MOVES_DB[bestMoveId].n}】！`, "#ffe066", 1.25);
    }
  }
}

function triggerCompanionBallModal() {
  if (!RUN) return;
  sfx("chest");
  enqueueModal(() => {
    const ov = document.getElementById("modal-ov");
    const box = document.getElementById("modal-box");
    ov.style.display = "flex";

    const ownedBaseIds = new Set(RUN.companions.map(c => c.baseId));
    const choices = [];

    if (RUN.companions.length < 5) {
      const avail = CHARACTERS.filter(c => c.id !== RUN.baseId && !ownedBaseIds.has(c.id));
      avail.sort(() => Math.random() - 0.5);
      for (const ch of avail.slice(0, 3)) {
        const previewComp = createCompanion(ch.id);
        const m = MOVES_DB[previewComp.moveId];
        choices.push({
          kind: "recruit",
          baseId: ch.id,
          title: `招募同伴【${POKEMON_ZH[previewComp.speciesId]}】(Lv.${previewComp.level})`,
          icon: `./assets/portraits/${previewComp.speciesId}.png`,
          tag: `第${ch.gen}世代御三家`,
          desc: `独立六维：物攻${previewComp.stats.atk}/特攻${previewComp.stats.spa}/速度${previewComp.stats.spe} · 携带原版技：【${m.n}】(${m.mn})`
        });
      }
    }

    for (const comp of RUN.companions) {
      const lsData = STARTER_LEARNSETS[comp.baseId];
      const nextMoveEntry = lsData.levelMoves.find(([mid, rlv]) => rlv > comp.level);
      const nextHint = nextMoveEntry ? `（Lv.${nextMoveEntry[1]} 将领悟【${MOVES_DB[nextMoveEntry[0]].n}】）` : "（已习得终极招式）";
      choices.push({
        kind: "train_comp",
        comp,
        title: `特训同伴【${POKEMON_ZH[comp.speciesId]}】连升 3 级 (Lv.${comp.level} ➔ Lv.${comp.level + 3})`,
        icon: `./assets/portraits/${comp.speciesId}.png`,
        tag: "神奇糖果特训",
        desc: `提升该同伴自身六维数值，当前招式：【${MOVES_DB[comp.moveId].n}】${nextHint}`
      });
    }

    const finalChoices = choices.slice(0, 4);
    let html = "";
    finalChoices.forEach((c, idx) => {
      html += `
        <button class="choice-btn evo-choice" data-pick="${idx}">
          <div class="choice-ic"><img src="${c.icon}" /></div>
          <div style="flex:1;">
            <div>
              <b style="font-size:15px;color:#fff;">${c.title}</b>
              <span class="choice-tag">${c.tag}</span>
            </div>
            <div style="font-size:11px;color:#d8c8a8;margin-top:3px;">${c.desc}</div>
          </div>
        </button>
      `;
    });

    box.innerHTML = `
      <div style="text-align:center;margin-bottom:8px;">
        <div style="font-size:20px;font-weight:900;color:#81d4fa;">🔴 发现同行宝可梦精灵球！</div>
        <div style="font-size:12px;color:#cbb98b;">同伴宝可梦拥有自主索敌走位 AI、独立六维数值与唯一技能，仅通过自身升级更换原版招式</div>
      </div>
      <div>${html}</div>
    `;

    box.querySelectorAll("[data-pick]").forEach(btn => {
      btn.onclick = () => {
        const c = finalChoices[parseInt(btn.getAttribute("data-pick"), 10)];
        if (c.kind === "recruit") {
          const nc = createCompanion(c.baseId);
          RUN.companions.push(nc);
          playCry(nc.speciesId);
          addPopup(RUN.x, RUN.y - 40, `🤝 同伴【${POKEMON_ZH[nc.speciesId]}】加入战斗！`, "#81d4fa", 1.3);
        } else if (c.kind === "train_comp") {
          for (let k = 0; k < 3; k++) gainCompanionXp(c.comp, c.comp.xpNeed);
          playCry(c.comp.speciesId);
        }
        updateHudSlots();
        closeCurrentModal();
      };
    });
  });
}

function triggerPlayerLevelUp() {
  RUN.level++;
  RUN.xp -= RUN.xpNeed;
  RUN.xpNeed = Math.round(18 + RUN.level * 9 + Math.pow(RUN.level, 1.32) * 3);
  sfx("level");

  const lsData = STARTER_LEARNSETS[RUN.baseId];
  let newStage = RUN.evoStage;
  if (RUN.level >= lsData.evoLevels[1]) newStage = 2;
  else if (RUN.level >= lsData.evoLevels[0]) newStage = 1;

  if (newStage > RUN.evoStage) {
    RUN.evoStage = newStage;
    RUN.speciesId = lsData.chain[newStage];
    playCry(RUN.speciesId);
    addPopup(RUN.x, RUN.y - 52, `✨ 进化为【${POKEMON_ZH[RUN.speciesId]}】！种族值大幅跃升！`, "#ffe066", 1.55);
  }

  const oldMaxHp = RUN.maxHp;
  RUN.stats = computePokemonStats(RUN.speciesId, RUN.level, true, false);
  RUN.maxHp = RUN.stats.maxHp;
  RUN.hp = Math.min(RUN.maxHp, RUN.hp + Math.max(8, RUN.maxHp - oldMaxHp + 6));
  updateHudSlots();

  for (const [mid, reqLv] of lsData.levelMoves) {
    if (reqLv <= RUN.level && !RUN.learnedHistory.has(mid)) {
      RUN.learnedHistory.add(mid);
      offerPlayerMove(mid, `Lv.${RUN.level} 升级领悟`);
    }
  }
}

// ============================================================================
// 12 Genuine Vampire Survivors + Brotato + Pokemon Move Mechanics!
// ============================================================================
function executeUnitMove(unit, moveId) {
  const m = MOVES_DB[moveId];
  if (!m) return;
  const col = TYPE_META[m.t]?.color || "#ffffff";
  const pat = m.pat;
  const isComp = !unit.isPlayerUnit;
  const scale = isComp ? 0.88 : 1.05;

  const target = nearestEnemy(unit.x, unit.y, 440);
  const aimAng = target ? Math.atan2(target.y - unit.y, target.x - unit.x) : Math.atan2(unit.facingY || 0, unit.facingX || 1);

  if (isComp) {
    // Dynamic companion attack lunge & occasional callout bubble!
    unit.lungeT = 0.18;
    unit.lungeDx = Math.cos(aimAng) * 14;
    unit.lungeDy = Math.sin(aimAng) * 14;
    if (Math.random() < 0.35 && unit.calloutT <= 0) {
      unit.calloutText = `${m.n}！`;
      unit.calloutT = 1.1;
    }
  }

  // 1. 【吸血鬼幸存者·鞭子 (Whip)】: Wide horizontal/directional lash front & back!
  if (pat === "vs_whip") {
    const dirs = m.p >= 85 ? [0, Math.PI] : [0];
    for (const dOffset of dirs) {
      const ang = (unit.facingX < 0 ? Math.PI : 0) + dOffset;
      RUN.meleeSwings.push({
        owner: unit,
        kind: "whip",
        ang,
        len: (m.p >= 90 ? 138 : 108) * scale,
        wid: 34 * scale,
        life: 0.24,
        maxLife: 0.24,
        color: col,
        attackerLv: unit.level,
        attackerStats: unit.stats,
        moveId,
        hitSet: new Set()
      });
    }
  }
  // 2. 【吸血鬼幸存者·国王圣经 (King Bible)】: Orbiting guardian blades/petals/flames!
  else if (pat === "vs_bible") {
    // Clear existing orbitals from the same unit + moveId so they refresh cleanly
    RUN.orbitals = RUN.orbitals.filter(o => !(o.owner === unit && o.moveId === moveId));
    const count = m.p >= 85 ? 5 : (m.p >= 55 ? 4 : 3);
    const radius = (m.p >= 85 ? 88 : 72) * scale;
    for (let i = 0; i < count; i++) {
      RUN.orbitals.push({
        owner: unit,
        moveId,
        ang: (i / count) * Math.PI * 2,
        dist: radius,
        r: 16 * scale,
        speed: m.t === "fire" ? 5.6 : 4.8,
        life: 2.35,
        color: col,
        attackerLv: unit.level,
        attackerStats: unit.stats,
        hitCd: new Map()
      });
    }
  }
  // 3. 【吸血鬼幸存者·十字架 (Cross Boomerang)】: Flies forward, hovers, then accelerates back through the unit!
  else if (pat === "vs_cross") {
    const count = m.h > 1 ? Math.min(3, m.h) : (m.p >= 75 ? 2 : 1);
    for (let i = 0; i < count; i++) {
      const ang = aimAng + (i - (count - 1) / 2) * 0.26;
      const spd = 380;
      RUN.boomerangs.push({
        owner: unit,
        x: unit.x,
        y: unit.y,
        vx: Math.cos(ang) * spd,
        vy: Math.sin(ang) * spd,
        ax: -Math.cos(ang) * 560,
        ay: -Math.sin(ang) * 560,
        r: 17 * scale,
        life: 1.65,
        age: 0,
        color: col,
        attackerLv: unit.level,
        attackerStats: unit.stats,
        moveId,
        hitSetOut: new Set(),
        hitSetBack: new Set()
      });
    }
  }
  // 4. 【吸血鬼幸存者·圣水 (Santa Water)】: Lobbed flask/seed that shatters into a persistent bubbling ground hazard pool!
  else if (pat === "vs_santa") {
    const count = m.p >= 85 ? 2 : 1;
    for (let i = 0; i < count; i++) {
      let tx = unit.x + Math.cos(aimAng + i * 1.2) * 115;
      let ty = unit.y + Math.sin(aimAng + i * 1.2) * 115;
      if (target && i === 0) {
        tx = target.x;
        ty = target.y;
      }
      RUN.projectiles.push({
        kind: "santa_bottle",
        x: unit.x,
        y: unit.y - 10,
        startX: unit.x,
        startY: unit.y,
        tx,
        ty,
        flightT: 0,
        flightDur: 0.36,
        r: 12 * scale,
        poolR: (m.p >= 85 ? 68 : 54) * scale,
        life: 0.4,
        color: col,
        attackerLv: unit.level,
        attackerStats: unit.stats,
        moveId,
        hitSet: new Set()
      });
    }
  }
  // 5. 【吸血鬼幸存者·大蒜 (Garlic Aura)】: Pulsing shockwave/drain barrier anchored to the caster!
  else if (pat === "vs_garlic") {
    const rad = (m.p >= 85 ? 96 : 76) * scale;
    RUN.zones.push({
      owner: unit,
      followOwner: true,
      x: unit.x,
      y: unit.y,
      r: rad,
      life: 0.35,
      maxLife: 0.35,
      color: col,
      kind: "garlic_ring",
      dmgTick: 0
    });
    for (const e of RUN.enemies) {
      if (Math.hypot(e.x - unit.x, e.y - unit.y) <= rad + e.radius) {
        hitEnemyWithMove(e, unit.level, unit.stats, moveId, 0.88);
        e.slowT = 0.8;
        if (!e.isBoss) {
          const pushA = Math.atan2(e.y - unit.y, e.x - unit.x);
          e.x += Math.cos(pushA) * 22;
          e.y += Math.sin(pushA) * 22;
        }
      }
    }
  }
  // 6. 【吸血鬼幸存者·符文追踪器 (Runetracer)】: High-speed ricochet ball bouncing off screen walls & enemies!
  else if (pat === "vs_runetracer") {
    const count = m.h > 1 ? 3 : (m.p >= 85 ? 2 : 1);
    for (let i = 0; i < count; i++) {
      const ang = aimAng + (i - (count - 1) / 2) * 0.32;
      RUN.projectiles.push({
        kind: "runetracer",
        x: unit.x,
        y: unit.y,
        vx: Math.cos(ang) * 470,
        vy: Math.sin(ang) * 470,
        r: 15 * scale,
        pierce: 99,
        bounce: 6,
        life: 2.3,
        color: col,
        trail: [],
        attackerLv: unit.level,
        attackerStats: unit.stats,
        moveId,
        aoeScale: 0.90,
        hitSet: new Set()
      });
    }
  }
  // 7. 【吸血鬼幸存者·斧头 (Gravity Axe)】: High parabolic lobbed boulder/hammer that crushes downward!
  else if (pat === "vs_axe") {
    const count = m.p >= 100 ? 3 : 2;
    for (let i = 0; i < count; i++) {
      const dirX = (target ? (target.x >= unit.x ? 1 : -1) : 1) * (i % 2 === 0 ? 1 : -0.8);
      RUN.projectiles.push({
        kind: "gravity_axe",
        x: unit.x,
        y: unit.y - 14,
        vx: dirX * (85 + i * 55 + Math.random() * 30),
        vy: -380 - i * 45,
        gravity: 860,
        r: 20 * scale,
        pierce: 6,
        life: 1.55,
        rot: 0,
        color: col,
        attackerLv: unit.level,
        attackerStats: unit.stats,
        moveId,
        aoeScale: 0.98,
        hitSet: new Set()
      });
    }
  }
  // 8. 【吸血鬼幸存者·闪电戒 (Sky Strike / Daimonji Fire Blast)】: Direct sky-call pillar/blast on enemy clusters!
  else if (pat === "vs_lightning") {
    const pool = RUN.enemies.filter(e => Math.hypot(e.x - unit.x, e.y - unit.y) < 420);
    const strikes = m.p >= 120 ? 3 : 2;
    for (let i = 0; i < strikes; i++) {
      const e = pool.length ? pool[i % pool.length] : null;
      const sx = e ? e.x : unit.x + Math.cos(aimAng + i * 1.5) * 140;
      const sy = e ? e.y : unit.y + Math.sin(aimAng + i * 1.5) * 140;
      const rad = (m.p >= 120 ? 74 : 58) * scale;
      RUN.zones.push({
        x: sx,
        y: sy,
        r: rad,
        life: 0.42,
        maxLife: 0.42,
        color: col,
        kind: m.id === 126 ? "daimonji" : "sky_pillar"
      });
      for (const mEnemy of RUN.enemies) {
        if (Math.hypot(mEnemy.x - sx, mEnemy.y - sy) <= rad + mEnemy.radius) {
          hitEnemyWithMove(mEnemy, unit.level, unit.stats, moveId, 0.92);
        }
      }
    }
  }
  // 9. 【土豆兄弟 (Brotato)·近战突刺与弧光挥砍 (Thrust & Cleave Melee)】: Physical weapon thrusts out & retracts!
  else if (pat === "br_thrust") {
    const count = m.h > 1 ? Math.min(3, m.h) : 1;
    for (let i = 0; i < count; i++) {
      const ang = aimAng + (i - (count - 1) / 2) * 0.25;
      RUN.meleeSwings.push({
        owner: unit,
        kind: (m.id === 163 || m.id === 348 || m.id === 400 || m.id === 534 || m.id === 895 || m.id === 663) ? "cleave" : "thrust",
        ang,
        len: (m.p >= 85 ? 112 : 88) * scale,
        wid: 28 * scale,
        life: 0.22,
        maxLife: 0.22,
        color: col,
        attackerLv: unit.level,
        attackerStats: unit.stats,
        moveId,
        hitSet: new Set()
      });
    }
  }
  // 10. 【宝可梦特色·本体残影猛扑冲撞 (Body Dash / Leap Slam)】: The Pokemon itself (or companion!) dashes through enemies!
  else if (pat === "pk_dash") {
    unit.dashT = 0.24;
    const dashSpd = isComp ? 460 : 410;
    unit.dashVx = Math.cos(aimAng) * dashSpd;
    unit.dashVy = Math.sin(aimAng) * dashSpd;
    unit.dashMoveId = moveId;
    unit.dashHitSet = new Set();
    if (!isComp) {
      RUN.invulnT = Math.max(RUN.invulnT, 0.30); // Brief dash i-frames so body-slamming feels heroic and safe!
    }
  }
  // 11. 【宝可梦特色·巨颚咬合 (Snapping Jaws)】
  else if (pat === "pk_jaw") {
    const fx = target ? target.x : unit.x + Math.cos(aimAng) * 78;
    const fy = target ? target.y : unit.y + Math.sin(aimAng) * 78;
    const rad = 58 * scale;
    RUN.zones.push({ x: fx, y: fy, r: rad, life: 0.28, maxLife: 0.28, color: col, kind: "fangs" });
    for (const e of RUN.enemies) {
      if (Math.hypot(e.x - fx, e.y - fy) <= rad + e.radius) {
        hitEnemyWithMove(e, unit.level, unit.stats, moveId, 1.05);
        e.rootT = 0.65; // Authentic Bite/Crunch Flinch!
      }
    }
  }
  // 12. 【宝可梦特色·贯穿全屏持续激光束 (Continuous Piercing Laser Beam)】
  else {
    const beamLen = (m.p >= 90 ? 440 : 320) * scale;
    const beamWid = (m.p >= 100 ? 26 : 16) * scale;
    RUN.lasers.push({
      owner: unit,
      ang: aimAng,
      len: beamLen,
      wid: beamWid,
      life: 0.28,
      maxLife: 0.28,
      color: col,
      attackerLv: unit.level,
      attackerStats: unit.stats,
      moveId,
      hitSet: new Set()
    });
  }
}

function hitEnemyWithMove(e, attackerLv, attackerStats, moveId, aoeScale = 1.0) {
  if (!e || e.hp <= 0) return;
  const res = calculatePokemonDamage(attackerLv, attackerStats, moveId, e.level, e.stats, aoeScale);
  e.hp -= res.dmg;
  e.flashT = 0.09;
  sfx("hit");

  const m = MOVES_DB[moveId];
  if (m && m.dr > 0 && RUN.hp < RUN.maxHp) {
    RUN.hp = Math.min(RUN.maxHp, RUN.hp + Math.max(1, Math.round(res.dmg * (m.dr / 100) * 0.45)));
  }
  if (m && m.t === "fire" && Math.random() < 0.25) e.burnT = 3.0;
  if (m && m.t === "ice" && Math.random() < 0.30) e.slowT = 1.6;

  let effText = "";
  let color = "#ffffff";
  if (res.eff >= 1.9) {
    effText = "效果绝佳! ";
    color = "#ffeb3b";
  } else if (res.eff <= 0.6) {
    effText = "效果不好 ";
    color = "#90a4ae";
  }
  if (res.isCrit) {
    effText = "💥要害! " + effText;
    color = "#ff8a65";
  }
  addPopup(e.x, e.y - 16, `${effText}${res.dmg}`, color, res.eff >= 1.9 || res.isCrit ? 1.15 : 0.92);

  if (e.hp <= 0) {
    killEnemy(e);
  }
}

function spawnEnemy(isBoss = false) {
  if (!RUN) return;
  const timeMin = RUN.time / 60;
  const enemyLv = Math.max(2, Math.round(3 + timeMin * 3.3 + RUN.stage.lvOffset + (isBoss ? 3 : 0)));

  let species = 19;
  if (isBoss) {
    const bp = RUN.bossPool;
    species = bp[RUN.bossIndex % bp.length];
    RUN.bossIndex++;
  } else {
    const wp = RUN.wildPool;
    const progress = Math.min(1.0, timeMin / 11.0);
    const maxIdx = Math.min(wp.length, Math.max(10, Math.floor((0.20 + progress * 0.80) * wp.length)));
    const minIdx = Math.min(maxIdx - 6, Math.floor(progress * 0.55 * wp.length));
    const idx = minIdx + Math.floor(Math.random() * Math.max(1, maxIdx - minIdx));
    species = wp[Math.max(0, Math.min(wp.length - 1, idx))];
  }

  const eStats = computePokemonStats(species, enemyLv, false, isBoss);
  const ang = Math.random() * Math.PI * 2;
  const dist = Math.max(canvas.width, canvas.height) * 0.55 + 55;

  const moveSpd = isBoss
    ? Math.min(88, 56 + eStats.spe * 0.18)
    : Math.min(112, 46 + eStats.spe * 0.28 + Math.min(20, timeMin * 1.5));

  const enemy = {
    species,
    level: enemyLv,
    stats: eStats,
    x: RUN.x + Math.cos(ang) * dist,
    y: RUN.y + Math.sin(ang) * dist,
    hp: eStats.maxHp,
    maxHp: eStats.maxHp,
    speed: moveSpd,
    radius: isBoss ? 34 : 17,
    scale: isBoss ? 2.45 : 1.5,
    isBoss,
    flashT: 0,
    slowT: 0,
    rootT: 0,
    leechT: 0,
    burnT: 0,
    skillTimer: isBoss ? 4.2 : 999,
    dashWarnT: 0,
    dashVx: 0,
    dashVy: 0,
    animOffset: Math.random() * 10
  };
  RUN.enemies.push(enemy);
  if (isBoss) {
    RUN.activeBoss = enemy;
    playCry(species);
    addPopup(RUN.x, RUN.y - 60, `👑 传说头目【Lv.${enemyLv} ${POKEMON_ZH[species]}】降临！`, "#ff5252", 1.45);
  }
}

function killEnemy(e) {
  RUN.kills++;
  if (RUN.activeBoss === e) RUN.activeBoss = null;

  const baseXp = Math.max(3, Math.round((e.stats.bst * e.level) / 210));
  if (e.isBoss) {
    spawnFieldTM(true);
    spawnCompanionBall(false, e.x, e.y);
    RUN.gems.push({ x: e.x + 18, y: e.y, xp: baseXp * 6, tier: 3, kind: "xp" });
    const gGain = Math.round(60 * RUN.stage.goldMul);
    RUN.gold += gGain;
    SAVE.gold += gGain;
    writeSave();
    addPopup(e.x, e.y - 24, `🎁 击败头目 ${POKEMON_ZH[e.species]}！掉落专属TM与同伴球！`, "#ff80ab", 1.3);
  } else {
    const roll = Math.random();
    if (roll < 0.022) {
      RUN.gems.push({ x: e.x, y: e.y, heal: Math.round(RUN.maxHp * 0.22), kind: "berry" });
    } else if (roll < 0.075) {
      RUN.gems.push({ x: e.x, y: e.y, gold: Math.round(10 * RUN.stage.goldMul), kind: "coin" });
    } else {
      const tier = e.level >= 28 ? 2 : (e.level >= 14 ? 1 : 0);
      RUN.gems.push({ x: e.x, y: e.y, xp: baseXp, tier, kind: "xp" });
    }
  }
}

function addPopup(x, y, text, color = "#fff", scale = 1.0) {
  if (!RUN || RUN.popups.length > 90) return;
  RUN.popups.push({ x: x + (Math.random() - 0.5) * 16, y, text, color, scale, life: 0.65, maxLife: 0.65 });
}

function nearestEnemy(x, y, maxDist = 9999) {
  let best = null;
  let bestD = maxDist * maxDist;
  for (const e of RUN.enemies) {
    const d2 = (e.x - x) * (e.x - x) + (e.y - y) * (e.y - y);
    if (d2 < bestD) { bestD = d2; best = e; }
  }
  return best;
}

function distToSegment(px, py, x1, y1, x2, y2) {
  const l2 = (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
  if (l2 === 0) return Math.hypot(px - x1, py - y1);
  let t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)));
}

function pauseRun() {
  if (!RUN || RUN.over || RUN.modalOpen) return;
  RUN.paused = true;
  const ov = document.getElementById("modal-ov");
  const box = document.getElementById("modal-box");
  ov.style.display = "flex";
  box.innerHTML = `
    <div style="text-align:center;padding:10px;">
      <div style="font-size:22px;font-weight:900;color:#ffe066;margin-bottom:10px;">⏸️ 暂停 · 队伍状态</div>
      <div style="font-size:13px;color:#ccc;margin-bottom:14px;">
        主控：<b>Lv.${RUN.level} ${POKEMON_ZH[RUN.speciesId]}</b> (HP ${Math.ceil(RUN.hp)}/${RUN.maxHp} · 物攻${RUN.stats.atk} · 特攻${RUN.stats.spa} · 物防${RUN.stats.def} · 特防${RUN.stats.spd} · 速度${RUN.stats.spe})<br/>
        同行同伴数：<b>${RUN.companions.length} / 5</b> · 击败数：<b>${RUN.kills}</b>
      </div>
      <div style="display:flex;gap:12px;justify-content:center;">
        <button id="btn-resume" class="vs-btn green" style="min-width:130px;">继续战斗</button>
        <button id="btn-quit" class="vs-btn" style="min-width:130px;">结算返回主菜单</button>
      </div>
    </div>
  `;
  box.querySelector("#btn-resume").onclick = resumeRun;
  box.querySelector("#btn-quit").onclick = () => endRun(false);
}

function resumeRun() {
  if (!RUN) return;
  document.getElementById("modal-ov").style.display = "none";
  RUN.modalOpen = false;
  RUN.paused = false;
}

function endRun(victory) {
  if (!RUN) return;
  RUN.over = true;
  RUN.paused = true;
  const timeBonusGold = Math.floor(RUN.time * 1.5);
  RUN.gold += timeBonusGold;
  SAVE.gold += timeBonusGold;
  if (RUN.kills > (SAVE.bestKills || 0)) SAVE.bestKills = RUN.kills;
  writeSave();

  const mins = String(Math.floor(RUN.time / 60)).padStart(2, "0");
  const secs = String(Math.floor(RUN.time % 60)).padStart(2, "0");

  const ov = document.getElementById("modal-ov");
  const box = document.getElementById("modal-box");
  ov.style.display = "flex";
  box.innerHTML = `
    <div style="text-align:center;padding:12px;">
      <div style="font-size:25px;font-weight:900;color:${victory ? "#ffe066" : "#ff5252"};margin-bottom:8px;">
        ${victory ? "🏆 殿堂级训练家！" : "💀 体力耗尽 · 冒险结算"}
      </div>
      <img src="./assets/portraits/${RUN.speciesId}.png" style="width:72px;height:72px;image-rendering:pixelated;border:2px solid #d4af37;border-radius:8px;margin-bottom:8px;" />
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;background:#160e22;padding:12px;border-radius:6px;margin-bottom:14px;font-size:13px;">
        <div>⏱️ 存活时间：<b style="color:#fff;">${mins}:${secs}</b></div>
        <div>💀 击败宝可梦：<b style="color:#fff;">${RUN.kills}</b></div>
        <div>⭐ 最终形态：<b style="color:#ffe066;">Lv.${RUN.level} ${POKEMON_ZH[RUN.speciesId]}</b></div>
        <div>🪙 获得金币：<b style="color:#ffd54f;">+${RUN.gold}</b></div>
      </div>
      <button id="btn-back-menu" class="vs-btn gold" style="width:200px;font-size:17px;">返回主菜单</button>
    </div>
  `;
  box.querySelector("#btn-back-menu").onclick = () => {
    ov.style.display = "none";
    document.getElementById("hud").style.display = "none";
    document.getElementById("scr-menu").style.display = "flex";
    RUN = null;
    playBgm("./assets/music/menu.ogg");
    renderMenu();
  };
}

// ============================================================================
// Main 60FPS Update Loop
// ============================================================================
let lastTime = performance.now();

function updateRun(dt) {
  if (!RUN || RUN.paused || RUN.over) return;
  RUN.time += dt;
  if (RUN.invulnT > 0) RUN.invulnT -= dt;

  // Player movement + Body Dash (`pk_dash`) physics
  const playerMoveSpd = Math.min(238, 142 + RUN.stats.spe * 0.42);
  if (RUN.dashT > 0) {
    RUN.dashT -= dt;
    RUN.x += RUN.dashVx * dt;
    RUN.y += RUN.dashVy * dt;
    RUN.vx = RUN.dashVx;
    RUN.vy = RUN.dashVy;
    RUN.afterimages.push({ pid: RUN.speciesId, x: RUN.x, y: RUN.y, vx: RUN.vx, vy: RUN.vy, scale: 1.85 + RUN.evoStage * 0.25, life: 0.18 });
    for (const e of RUN.enemies) {
      if (e.hp > 0 && !RUN.dashHitSet.has(e) && Math.hypot(e.x - RUN.x, e.y - RUN.y) <= e.radius + 28) {
        RUN.dashHitSet.add(e);
        hitEnemyWithMove(e, RUN.level, RUN.stats, RUN.dashMoveId, 1.0);
        if (!e.isBoss) {
          const a = Math.atan2(e.y - RUN.y, e.x - RUN.x);
          e.x += Math.cos(a) * 36;
          e.y += Math.sin(a) * 36;
        }
      }
    }
  } else {
    let mx = JOY.active ? JOY.dx : 0;
    let my = JOY.active ? JOY.dy : 0;
    if (KEYS.has("KeyW") || KEYS.has("ArrowUp")) my -= 1;
    if (KEYS.has("KeyS") || KEYS.has("ArrowDown")) my += 1;
    if (KEYS.has("KeyA") || KEYS.has("ArrowLeft")) mx -= 1;
    if (KEYS.has("KeyD") || KEYS.has("ArrowRight")) mx += 1;

    const mlen = Math.hypot(mx, my);
    if (mlen > 0.01) {
      mx /= mlen; my /= mlen;
      RUN.x += mx * playerMoveSpd * dt;
      RUN.y += my * playerMoveSpd * dt;
      RUN.vx = mx; RUN.vy = my;
      RUN.facingX = mx; RUN.facingY = my;
    } else {
      RUN.vx = 0; RUN.vy = 0;
    }
  }

  // 1. Fire Player's Equipped Moves (Up to 4 Moves)
  for (const mSlot of RUN.moves) {
    mSlot.timer -= dt;
    if (mSlot.timer <= 0) {
      mSlot.timer = computeMoveCooldown(mSlot.id, RUN.stats);
      executeUnitMove(RUN, mSlot.id);
    }
  }

  // 2. Dynamic Autonomous Companion AI (Hunting, Kiting, Body Lunges, Smart Leash!)
  const numComps = RUN.companions.length;
  for (let i = 0; i < numComps; i++) {
    const comp = RUN.companions[i];
    if (comp.calloutT > 0) comp.calloutT -= dt;
    if (comp.lungeT > 0) comp.lungeT -= dt;

    if (comp.dashT > 0) {
      // Companion is mid-dash (`pk_dash`)!
      comp.dashT -= dt;
      comp.x += comp.dashVx * dt;
      comp.y += comp.dashVy * dt;
      comp.vx = comp.dashVx;
      comp.vy = comp.dashVy;
      RUN.afterimages.push({ pid: comp.speciesId, x: comp.x, y: comp.y, vx: comp.vx, vy: comp.vy, scale: 1.55 + comp.evoStage * 0.2, life: 0.16 });
      for (const e of RUN.enemies) {
        if (e.hp > 0 && !comp.dashHitSet.has(e) && Math.hypot(e.x - comp.x, e.y - comp.y) <= e.radius + 26) {
          comp.dashHitSet.add(e);
          hitEnemyWithMove(e, comp.level, comp.stats, comp.dashMoveId, 0.95);
        }
      }
    } else {
      const m = MOVES_DB[comp.moveId];
      const isMeleeComp = m && (m.pat === "br_thrust" || m.pat === "vs_whip" || m.pat === "vs_bible" || m.pat === "vs_garlic" || m.pat === "pk_dash" || m.pat === "pk_jaw");
      const distToPlayer = Math.hypot(comp.x - RUN.x, comp.y - RUN.y);
      const cSpd = Math.min(245, 148 + comp.stats.spe * 0.45);
      const foe = nearestEnemy(comp.x, comp.y, 260);

      let goalX = RUN.x;
      let goalY = RUN.y;

      if (distToPlayer > 250 || !foe) {
        // Patrol dynamically around player when far or no nearby enemies
        comp.patrolAng += dt * (1.2 + (i % 3) * 0.35);
        const patrolR = 55 + (i % 2) * 28;
        goalX = RUN.x + Math.cos(comp.patrolAng + (i * Math.PI * 2) / numComps) * patrolR;
        goalY = RUN.y + Math.sin(comp.patrolAng + (i * Math.PI * 2) / numComps) * patrolR;
      } else if (isMeleeComp) {
        // Melee / Bible / Aura companion actively hunts and circles the target monster!
        const angToFoe = Math.atan2(comp.y - foe.y, comp.x - foe.x) + dt * 2.2;
        const engageDist = (m.pat === "vs_bible" || m.pat === "vs_garlic") ? 58 : 34;
        goalX = foe.x + Math.cos(angToFoe) * engageDist;
        goalY = foe.y + Math.sin(angToFoe) * engageDist;
      } else {
        // Ranged / Artillery companion kites at optimal mid-range (135px) while orbiting target
        const angToFoe = Math.atan2(comp.y - foe.y, comp.x - foe.x) + dt * 1.4;
        goalX = foe.x + Math.cos(angToFoe) * 135;
        goalY = foe.y + Math.sin(angToFoe) * 135;
      }

      // Soft separation between companions so they never stack on top of each other
      for (let j = 0; j < numComps; j++) {
        if (i === j) continue;
        const other = RUN.companions[j];
        const sd = Math.hypot(comp.x - other.x, comp.y - other.y);
        if (sd < 38 && sd > 0.1) {
          goalX += ((comp.x - other.x) / sd) * 26;
          goalY += ((comp.y - other.y) / sd) * 26;
        }
      }

      const dx = goalX - comp.x;
      const dy = goalY - comp.y;
      const d = Math.hypot(dx, dy);
      if (d > 4) {
        comp.vx = (dx / d) * Math.min(cSpd, d * 5.5);
        comp.vy = (dy / d) * Math.min(cSpd, d * 5.5);
        comp.x += comp.vx * dt;
        comp.y += comp.vy * dt;
        comp.facingX = comp.vx;
        comp.facingY = comp.vy;
      }
    }

    comp.timer -= dt;
    if (comp.timer <= 0) {
      comp.timer = computeMoveCooldown(comp.moveId, comp.stats);
      executeUnitMove(comp, comp.moveId);
    }
  }

  // 3. Update Orbiting Guardian Blades (`vs_bible`)
  for (let i = RUN.orbitals.length - 1; i >= 0; i--) {
    const o = RUN.orbitals[i];
    o.life -= dt;
    if (o.life <= 0 || !o.owner) { RUN.orbitals.splice(i, 1); continue; }
    o.ang += o.speed * dt;
    o.x = o.owner.x + Math.cos(o.ang) * o.dist;
    o.y = o.owner.y + Math.sin(o.ang) * o.dist;
    for (const e of RUN.enemies) {
      if (e.hp > 0 && Math.hypot(e.x - o.x, e.y - o.y) <= o.r + e.radius) {
        const lastT = o.hitCd.get(e) || -99;
        if (RUN.time - lastT >= 0.38) {
          o.hitCd.set(e, RUN.time);
          hitEnemyWithMove(e, o.attackerLv, o.attackerStats, o.moveId, 0.72);
        }
      }
    }
  }

  // 4. Update Cross Boomerangs (`vs_cross`)
  for (let i = RUN.boomerangs.length - 1; i >= 0; i--) {
    const b = RUN.boomerangs[i];
    b.life -= dt;
    b.age += dt;
    if (b.life <= 0) { RUN.boomerangs.splice(i, 1); continue; }

    if (b.age > 0.45 && b.owner) {
      // Accelerate back toward its owner!
      const toOx = b.owner.x - b.x;
      const toOy = b.owner.y - b.y;
      const distO = Math.hypot(toOx, toOy);
      if (distO < 24 && b.age > 0.7) {
        RUN.boomerangs.splice(i, 1);
        continue;
      }
      if (distO > 1) {
        b.vx += (toOx / distO) * 980 * dt;
        b.vy += (toOy / distO) * 980 * dt;
      }
    } else {
      b.vx += b.ax * dt;
      b.vy += b.ay * dt;
    }
    b.x += b.vx * dt;
    b.y += b.vy * dt;

    const activeSet = b.age <= 0.45 ? b.hitSetOut : b.hitSetBack;
    for (const e of RUN.enemies) {
      if (e.hp > 0 && !activeSet.has(e) && Math.hypot(e.x - b.x, e.y - b.y) <= b.r + e.radius) {
        activeSet.add(e);
        hitEnemyWithMove(e, b.attackerLv, b.attackerStats, b.moveId, 0.88);
      }
    }
  }

  // 5. Update Brotato Melee Thrusts/Cleaves & VS Horizontal Whips (`br_thrust`, `vs_whip`)
  for (let i = RUN.meleeSwings.length - 1; i >= 0; i--) {
    const sw = RUN.meleeSwings[i];
    sw.life -= dt;
    if (sw.life <= 0 || !sw.owner) { RUN.meleeSwings.splice(i, 1); continue; }
    const prog = 1 - sw.life / sw.maxLife;
    // Extend out in first half, retract in second half (Brotato style!)
    const ext = sw.kind === "thrust" ? Math.sin(prog * Math.PI) : 1.0;
    const x1 = sw.owner.x;
    const y1 = sw.owner.y;
    const curAng = sw.kind === "cleave" ? (sw.ang - 0.65 + prog * 1.3) : sw.ang;
    const x2 = x1 + Math.cos(curAng) * sw.len * ext;
    const y2 = y1 + Math.sin(curAng) * sw.len * ext;
    sw.x1 = x1; sw.y1 = y1; sw.x2 = x2; sw.y2 = y2; sw.curAng = curAng;

    for (const e of RUN.enemies) {
      if (e.hp > 0 && !sw.hitSet.has(e)) {
        if (distToSegment(e.x, e.y, x1, y1, x2, y2) <= sw.wid * 0.5 + e.radius) {
          sw.hitSet.add(e);
          hitEnemyWithMove(e, sw.attackerLv, sw.attackerStats, sw.moveId, 0.96);
          if (!e.isBoss) {
            e.x += Math.cos(curAng) * 28;
            e.y += Math.sin(curAng) * 28;
          }
        }
      }
    }
  }

  // 6. Update Continuous Piercing Lasers (`pk_laser`)
  for (let i = RUN.lasers.length - 1; i >= 0; i--) {
    const ls = RUN.lasers[i];
    ls.life -= dt;
    if (ls.life <= 0 || !ls.owner) { RUN.lasers.splice(i, 1); continue; }
    const x1 = ls.owner.x;
    const y1 = ls.owner.y;
    const x2 = x1 + Math.cos(ls.ang) * ls.len;
    const y2 = y1 + Math.sin(ls.ang) * ls.len;
    ls.x1 = x1; ls.y1 = y1; ls.x2 = x2; ls.y2 = y2;
    for (const e of RUN.enemies) {
      if (e.hp > 0 && !ls.hitSet.has(e)) {
        if (distToSegment(e.x, e.y, x1, y1, x2, y2) <= ls.wid * 0.5 + e.radius) {
          ls.hitSet.add(e);
          hitEnemyWithMove(e, ls.attackerLv, ls.attackerStats, ls.moveId, 0.92);
        }
      }
    }
  }

  // 7. Update Projectiles (`santa_bottle`, `runetracer`, `gravity_axe`)
  const halfW = canvas.width * 0.48;
  const halfH = canvas.height * 0.48;
  for (let i = RUN.projectiles.length - 1; i >= 0; i--) {
    const p = RUN.projectiles[i];
    p.life -= dt;

    if (p.kind === "santa_bottle") {
      p.flightT += dt;
      const u = Math.min(1, p.flightT / p.flightDur);
      p.x = p.startX + (p.tx - p.startX) * u;
      p.y = p.startY + (p.ty - p.startY) * u - Math.sin(u * Math.PI) * 65;
      if (u >= 1) {
        // Shatter into a persistent Santa Water ground hazard pool!
        RUN.zones.push({
          x: p.tx,
          y: p.ty,
          r: p.poolR,
          life: 3.2,
          maxLife: 3.2,
          color: p.color,
          kind: "santa_pool",
          tick: 0.05,
          attackerLv: p.attackerLv,
          attackerStats: p.attackerStats,
          moveId: p.moveId
        });
        RUN.projectiles.splice(i, 1);
      }
      continue;
    }

    if (p.life <= 0) { RUN.projectiles.splice(i, 1); continue; }

    if (p.gravity) {
      p.vy += p.gravity * dt;
      p.rot = (p.rot || 0) + 10 * dt;
    }
    p.x += p.vx * dt;
    p.y += p.vy * dt;

    if (p.kind === "runetracer") {
      p.trail.push({ x: p.x, y: p.y });
      if (p.trail.length > 7) p.trail.shift();
      // Bounce off screen edges around the camera!
      if (p.bounce > 0) {
        if ((p.x - RUN.x < -halfW && p.vx < 0) || (p.x - RUN.x > halfW && p.vx > 0)) {
          p.vx = -p.vx; p.bounce--; p.hitSet.clear();
        }
        if ((p.y - RUN.y < -halfH && p.vy < 0) || (p.y - RUN.y > halfH && p.vy > 0)) {
          p.vy = -p.vy; p.bounce--; p.hitSet.clear();
        }
      }
    }

    for (const e of RUN.enemies) {
      if (e.hp <= 0 || p.hitSet.has(e)) continue;
      if (Math.hypot(e.x - p.x, e.y - p.y) <= p.r + e.radius) {
        p.hitSet.add(e);
        hitEnemyWithMove(e, p.attackerLv, p.attackerStats, p.moveId, p.aoeScale || 0.9);
        p.pierce--;
        if (p.pierce <= 0) { p.life = 0; break; }
      }
    }
  }

  // 8. Update Zones (including persistent ticking `santa_pool`)
  for (let i = RUN.zones.length - 1; i >= 0; i--) {
    const z = RUN.zones[i];
    z.life -= dt;
    if (z.life <= 0) { RUN.zones.splice(i, 1); continue; }
    if (z.followOwner && z.owner) {
      z.x = z.owner.x;
      z.y = z.owner.y;
    }
    if (z.kind === "santa_pool") {
      z.tick -= dt;
      if (z.tick <= 0) {
        z.tick = 0.48;
        for (const e of RUN.enemies) {
          if (e.hp > 0 && Math.hypot(e.x - z.x, e.y - z.y) <= z.r + e.radius) {
            hitEnemyWithMove(e, z.attackerLv, z.attackerStats, z.moveId, 0.52);
            e.slowT = 0.7;
            if (z.moveId === 73) e.leechT = 2.5;
          }
        }
      }
    }
  }

  for (let i = RUN.afterimages.length - 1; i >= 0; i--) {
    RUN.afterimages[i].life -= dt;
    if (RUN.afterimages[i].life <= 0) RUN.afterimages.splice(i, 1);
  }

  // 9. Spawn Wild Pokemon, Legal Field TMs, Companion PokeBalls, and Authentic Bosses
  const targetEnemyCap = Math.min(85, 18 + Math.floor(RUN.time * 0.22));
  RUN.spawnAcc += dt * (1.5 + RUN.time * 0.018);
  while (RUN.spawnAcc >= 1 && RUN.enemies.length < targetEnemyCap) {
    RUN.spawnAcc -= 1;
    spawnEnemy(false);
  }

  RUN.tmSpawnAcc -= dt;
  if (RUN.tmSpawnAcc <= 0) {
    RUN.tmSpawnAcc = 22;
    spawnFieldTM(false);
  }

  RUN.ballSpawnAcc -= dt;
  if (RUN.ballSpawnAcc <= 0) {
    RUN.ballSpawnAcc = 30;
    spawnCompanionBall(false);
  }

  RUN.bossAcc -= dt;
  if (RUN.bossAcc <= 0) {
    RUN.bossAcc = 48;
    spawnEnemy(true);
  }

  // 10. Update Enemies & Contact Damage
  for (let i = RUN.enemies.length - 1; i >= 0; i--) {
    const e = RUN.enemies[i];
    if (e.hp <= 0) { RUN.enemies.splice(i, 1); continue; }
    if (e.flashT > 0) e.flashT -= dt;
    if (e.slowT > 0) e.slowT -= dt;
    if (e.rootT > 0) e.rootT -= dt;

    if (e.leechT > 0) {
      e.leechT -= dt;
      if (Math.random() < dt * 2.0) {
        const drainAmt = Math.max(1, Math.round(e.maxHp * 0.04));
        e.hp -= drainAmt;
        RUN.hp = Math.min(RUN.maxHp, RUN.hp + Math.max(1, Math.round(drainAmt * 0.5)));
        if (e.hp <= 0) { killEnemy(e); continue; }
      }
    }
    if (e.burnT > 0) {
      e.burnT -= dt;
      if (Math.random() < dt * 2.0) {
        e.hp -= Math.max(1, Math.round(e.maxHp * 0.035));
        if (e.hp <= 0) { killEnemy(e); continue; }
      }
    }

    const dx = RUN.x - e.x;
    const dy = RUN.y - e.y;
    const dist = Math.hypot(dx, dy);

    if (!e.isBoss && dist > Math.max(canvas.width, canvas.height) * 0.95) {
      const ang = Math.random() * Math.PI * 2;
      const rDist = Math.max(canvas.width, canvas.height) * 0.55;
      e.x = RUN.x + Math.cos(ang) * rDist;
      e.y = RUN.y + Math.sin(ang) * rDist;
      continue;
    }

    if (e.isBoss) {
      e.skillTimer -= dt;
      if (e.skillTimer <= 0 && dist < 380) {
        e.skillTimer = 5.5;
        e.dashWarnT = 0.75;
        const a = Math.atan2(dy, dx);
        e.dashVx = Math.cos(a) * 240;
        e.dashVy = Math.sin(a) * 240;
      }
    }

    if (e.dashWarnT > 0) {
      e.dashWarnT -= dt;
      if (e.dashWarnT <= 0.35) {
        e.x += e.dashVx * dt;
        e.y += e.dashVy * dt;
      }
    } else {
      const spd = e.rootT > 0 ? 0 : e.speed * (e.slowT > 0 ? 0.52 : 1.0);
      if (dist > 1) {
        e.vx = (dx / dist) * spd;
        e.vy = (dy / dist) * spd;
        e.x += e.vx * dt;
        e.y += e.vy * dt;
      }
    }

    if (dist < e.radius + 15 && RUN.invulnT <= 0) {
      RUN.invulnT = 0.32;
      const usePhys = e.stats.atk >= e.stats.spa;
      let eAtk = usePhys ? e.stats.atk : e.stats.spa;
      if (usePhys && e.burnT > 0) eAtk = Math.floor(eAtk * 0.5);
      const pDef = Math.max(1, usePhys ? RUN.stats.def : RUN.stats.spd);
      const eff = getTypeEffectiveness(e.stats.types[0], RUN.stats.types);
      const rawHit = (((2 * e.level / 5 + 2) * (e.isBoss ? 52 : 34) * (eAtk / pDef)) / 50 + 2) * eff;
      const dmgTaken = Math.max(2, Math.round(rawHit));
      RUN.hp -= dmgTaken;
      addPopup(RUN.x, RUN.y - 22, `-${dmgTaken}`, "#ff5252", 1.1);
      updateHudSlots();
      if (RUN.hp <= 0) {
        endRun(false);
        return;
      }
    }
  }

  for (let i = RUN.fieldTMs.length - 1; i >= 0; i--) {
    const tm = RUN.fieldTMs[i];
    if (Math.hypot(RUN.x - tm.x, RUN.y - tm.y) < 30) {
      RUN.fieldTMs.splice(i, 1);
      offerPlayerMove(tm.moveId, "拾取场地技能机");
      break;
    }
  }

  for (let i = RUN.fieldBalls.length - 1; i >= 0; i--) {
    const b = RUN.fieldBalls[i];
    if (Math.hypot(RUN.x - b.x, RUN.y - b.y) < 30) {
      RUN.fieldBalls.splice(i, 1);
      triggerCompanionBallModal();
      break;
    }
  }

  for (let i = RUN.gems.length - 1; i >= 0; i--) {
    const g = RUN.gems[i];
    const d = Math.hypot(RUN.x - g.x, RUN.y - g.y);
    if (d < 98 || g.magnetized) {
      g.magnetized = true;
      const ang = Math.atan2(RUN.y - g.y, RUN.x - g.x);
      g.x += Math.cos(ang) * 440 * dt;
      g.y += Math.sin(ang) * 440 * dt;
    }
    if (d < 22) {
      RUN.gems.splice(i, 1);
      sfx("gem");
      if (g.kind === "berry") {
        RUN.hp = Math.min(RUN.maxHp, RUN.hp + g.heal);
        addPopup(RUN.x, RUN.y - 24, `+${g.heal} HP`, "#69f0ae", 1.05);
        updateHudSlots();
      } else if (g.kind === "coin") {
        RUN.gold += g.gold;
        SAVE.gold += g.gold;
        addPopup(RUN.x, RUN.y - 24, `+${g.gold} 🪙`, "#ffd54f", 1.0);
      } else {
        RUN.xp += g.xp;
        for (const comp of RUN.companions) {
          gainCompanionXp(comp, Math.max(1, Math.round(g.xp * 0.85)));
        }
        if (RUN.xp >= RUN.xpNeed) {
          triggerPlayerLevelUp();
        }
        updateHudSlots();
      }
    }
  }

  for (let i = RUN.popups.length - 1; i >= 0; i--) {
    const p = RUN.popups[i];
    p.life -= dt;
    p.y -= 26 * dt;
    if (p.life <= 0) RUN.popups.splice(i, 1);
  }

  document.getElementById("xp-fill").style.width = `${Math.min(100, (RUN.xp / RUN.xpNeed) * 100)}%`;
  document.getElementById("xp-lv").textContent = `LV.${RUN.level} ${POKEMON_ZH[RUN.speciesId]} (EXP ${RUN.xp}/${RUN.xpNeed})`;
  const mins = String(Math.floor(RUN.time / 60)).padStart(2, "0");
  const secs = String(Math.floor(RUN.time % 60)).padStart(2, "0");
  document.getElementById("hud-timer").textContent = `${mins}:${secs}`;
  document.getElementById("hud-wave").textContent = `野生Lv.${Math.max(2, Math.round(3 + (RUN.time / 60) * 3.3 + RUN.stage.lvOffset))} · ${RUN.stage.name.split(" ")[0]}`;
  document.getElementById("hud-kills").textContent = RUN.kills;
  document.getElementById("hud-gold").textContent = RUN.gold;

  const bossBar = document.getElementById("boss-bar");
  if (RUN.activeBoss && RUN.activeBoss.hp > 0) {
    bossBar.style.display = "block";
    document.getElementById("boss-name").textContent = `👑 传说大Boss【Lv.${RUN.activeBoss.level} ${POKEMON_ZH[RUN.activeBoss.species]}】(${Math.ceil(RUN.activeBoss.hp)} / ${Math.ceil(RUN.activeBoss.maxHp)})`;
    document.getElementById("boss-fill").style.width = `${Math.max(0, (RUN.activeBoss.hp / RUN.activeBoss.maxHp) * 100)}%`;
  } else {
    bossBar.style.display = "none";
  }
}

// ============================================================================
// Render 2D Battlefield & All 12 Distinct Combat Mechanics
// ============================================================================
function render2D() {
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);

  const st = RUN ? RUN.stage : (STAGES.find(s => s.id === SAVE.selectedStage) || STAGES[0]);
  const camX = RUN ? RUN.x - w / 2 : performance.now() * 0.025;
  const camY = RUN ? RUN.y - h / 2 : performance.now() * 0.015;

  ctx.fillStyle = st.bgTint;
  ctx.fillRect(0, 0, w, h);

  const gImg = getImg(st.groundTex);
  const pImg = getImg(st.pathTex);
  const tileSize = 128;
  const startCol = Math.floor(camX / tileSize) - 1;
  const endCol = Math.floor((camX + w) / tileSize) + 1;
  const startRow = Math.floor(camY / tileSize) - 1;
  const endRow = Math.floor((camY + h) / tileSize) + 1;

  for (let r = startRow; r <= endRow; r++) {
    for (let c = startCol; c <= endCol; c++) {
      const sx = Math.floor(c * tileSize - camX);
      const sy = Math.floor(r * tileSize - camY);
      const hash = Math.abs((c * 73856093) ^ (r * 19349663)) % 100;
      const tex = (hash < 18 && pImg.complete && pImg.naturalWidth > 0) ? pImg : gImg;
      if (tex.complete && tex.naturalWidth > 0) {
        ctx.drawImage(tex, sx, sy, tileSize + 1, tileSize + 1);
      }
    }
  }

  if (!RUN) return;

  // 1. Draw Ground Zones (Santa Water Pools, Garlic Rings, Sky Pillars, Daimonji Fire Blast, Snapping Jaws)
  for (const z of RUN.zones) {
    const sx = z.x - camX;
    const sy = z.y - camY;
    const alpha = Math.min(1, z.life / z.maxLife);
    ctx.save();
    if (z.kind === "santa_pool") {
      // Bubbling Santa Water Ground Hazard Pool!
      ctx.fillStyle = z.color;
      ctx.globalAlpha = 0.34 * Math.min(1, z.life);
      ctx.beginPath();
      ctx.arc(sx, sy, z.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 2;
      ctx.globalAlpha = 0.65 * Math.min(1, z.life);
      for (let b = 0; b < 4; b++) {
        const ba = RUN.time * 3 + b * 1.57;
        const br = z.r * (0.35 + ((RUN.time * 2 + b * 0.3) % 0.55));
        ctx.beginPath();
        ctx.arc(sx + Math.cos(ba) * br, sy + Math.sin(ba) * br, 5, 0, Math.PI * 2);
        ctx.stroke();
      }
    } else if (z.kind === "garlic_ring") {
      // Vampire Survivors Garlic Concentric Ripple Aura!
      ctx.strokeStyle = z.color;
      ctx.lineWidth = 3.5;
      ctx.globalAlpha = alpha * 0.85;
      ctx.beginPath();
      ctx.arc(sx, sy, z.r * (1 - alpha * 0.25), 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = z.color;
      ctx.globalAlpha = alpha * 0.18;
      ctx.fill();
    } else if (z.kind === "daimonji") {
      // Fire Blast "大" (Daimonji) kanji fire sigil!
      ctx.strokeStyle = "#ff3d00";
      ctx.lineWidth = 10;
      ctx.lineCap = "round";
      ctx.globalAlpha = alpha;
      const r = z.r * 0.85;
      ctx.beginPath();
      ctx.moveTo(sx - r, sy - r * 0.25); ctx.lineTo(sx + r, sy - r * 0.25);
      ctx.moveTo(sx, sy - r); ctx.lineTo(sx - r * 0.85, sy + r * 0.9);
      ctx.moveTo(sx, sy - r * 0.1); ctx.lineTo(sx + r * 0.85, sy + r * 0.9);
      ctx.stroke();
    } else if (z.kind === "sky_pillar") {
      // Sky Strike Vertical Beam Pillar + Ground Shockwave!
      const grad = ctx.createLinearGradient(sx - z.r * 0.5, sy, sx + z.r * 0.5, sy);
      grad.addColorStop(0, "rgba(255,255,255,0)");
      grad.addColorStop(0.5, z.color);
      grad.addColorStop(1, "rgba(255,255,255,0)");
      ctx.fillStyle = grad;
      ctx.globalAlpha = alpha * 0.85;
      ctx.fillRect(sx - z.r * 0.55, sy - 320, z.r * 1.1, 320);
      ctx.beginPath();
      ctx.arc(sx, sy, z.r, 0, Math.PI * 2);
      ctx.fill();
    } else if (z.kind === "fangs") {
      ctx.fillStyle = z.color;
      ctx.globalAlpha = alpha * 0.92;
      for (let t = -2; t <= 2; t++) {
        ctx.beginPath();
        ctx.moveTo(sx + t * 14 - 6, sy - 24 * alpha);
        ctx.lineTo(sx + t * 14 + 6, sy - 24 * alpha);
        ctx.lineTo(sx + t * 14, sy - 2);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(sx + t * 14 - 6, sy + 24 * alpha);
        ctx.lineTo(sx + t * 14 + 6, sy + 24 * alpha);
        ctx.lineTo(sx + t * 14, sy + 2);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  // 2. Draw Field Legal TMs & Companion Balls
  const tmDiscImg = getImg("./assets/items/tm-normal.png");
  for (const tm of RUN.fieldTMs) {
    const sx = tm.x - camX;
    const sy = tm.y - camY;
    const m = MOVES_DB[tm.moveId];
    const tMeta = TYPE_META[m.t];
    ctx.save();
    ctx.fillStyle = tMeta.color;
    ctx.globalAlpha = 0.32;
    ctx.beginPath();
    ctx.arc(sx, sy, 22 + Math.sin(RUN.time * 5) * 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1.0;
    const iconImg = getImg(tMeta.icon);
    if (iconImg.complete) ctx.drawImage(iconImg, sx - 14, sy - 14, 28, 28);
    else if (tmDiscImg.complete) ctx.drawImage(tmDiscImg, sx - 14, sy - 14, 28, 28);
    ctx.font = "900 11px monospace, sans-serif";
    ctx.textAlign = "center";
    ctx.fillStyle = "#000";
    ctx.fillText(`💿${m.n}[${m.mn.split("】")[0].replace("【", "")}]`, sx + 1, sy - 19);
    ctx.fillStyle = "#ffe066";
    ctx.fillText(`💿${m.n}[${m.mn.split("】")[0].replace("【", "")}]`, sx, sy - 20);
    ctx.restore();
  }

  const ballImg = getImg("./assets/items/poke-ball.png");
  for (const b of RUN.fieldBalls) {
    const sx = b.x - camX;
    const sy = b.y - camY;
    ctx.save();
    ctx.fillStyle = "rgba(79, 195, 247, 0.32)";
    ctx.beginPath();
    ctx.arc(sx, sy, 22 + Math.cos(RUN.time * 5) * 3, 0, Math.PI * 2);
    ctx.fill();
    if (ballImg.complete) ctx.drawImage(ballImg, sx - 15, sy - 15, 30, 30);
    ctx.font = "900 11px monospace, sans-serif";
    ctx.textAlign = "center";
    ctx.fillStyle = "#000";
    ctx.fillText("🔴同伴精灵球", sx + 1, sy - 19);
    ctx.fillStyle = "#81d4fa";
    ctx.fillText("🔴同伴精灵球", sx, sy - 20);
    ctx.restore();
  }

  // 3. Draw XP Gems, Berries & Coins
  const berryImg = getImg("./assets/items/sitrus-berry.png");
  const coinImg = getImg("./assets/ui/icons/coin.png");
  for (const g of RUN.gems) {
    const sx = g.x - camX;
    const sy = g.y - camY;
    if (sx < -30 || sx > w + 30 || sy < -30 || sy > h + 30) continue;
    if (g.kind === "berry" && berryImg.complete) {
      ctx.drawImage(berryImg, sx - 12, sy - 12, 24, 24);
    } else if (g.kind === "coin" && coinImg.complete) {
      ctx.drawImage(coinImg, sx - 11, sy - 11, 22, 22);
    } else {
      const colors = ["#29b6f6", "#66bb6a", "#ff5252", "#e040fb"];
      ctx.fillStyle = colors[g.tier || 0];
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(sx, sy - 8);
      ctx.lineTo(sx + 6, sy);
      ctx.lineTo(sx, sy + 8);
      ctx.lineTo(sx - 6, sy);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
  }

  // 4. Draw Dash Afterimages (`pk_dash`)
  for (const ai of RUN.afterimages) {
    ctx.save();
    ctx.globalAlpha = (ai.life / 0.18) * 0.48;
    drawPokemonSprite(ctx, ai.pid, ai.x - camX, ai.y - camY, ai.vx, ai.vy, RUN.time, ai.scale, true, null, 0);
    ctx.restore();
  }

  // 5. Sort & Draw Enemies, Dynamic Companions, and Player
  const renderList = [];
  for (const e of RUN.enemies) {
    const sx = e.x - camX;
    const sy = e.y - camY;
    if (sx < -90 || sx > w + 90 || sy < -90 || sy > h + 90) continue;
    renderList.push({ type: "enemy", y: e.y, obj: e, sx, sy });
  }
  for (const comp of RUN.companions) {
    renderList.push({ type: "comp", y: comp.y, obj: comp, sx: comp.x - camX, sy: comp.y - camY });
  }
  renderList.push({ type: "player", y: RUN.y, sx: w / 2, sy: h / 2 });
  renderList.sort((a, b) => a.y - b.y);

  ctx.textAlign = "center";
  for (const item of renderList) {
    if (item.type === "enemy") {
      const e = item.obj;
      drawPokemonSprite(ctx, e.species, item.sx, item.sy, e.vx || 0, e.vy || 1, RUN.time + e.animOffset, e.scale, e.flashT > 0, e.isBoss ? "#ff4444" : null, 0);
      const bw = e.isBoss ? 68 : 34;
      const bh = e.isBoss ? 6 : 4;
      const bx = item.sx - bw / 2;
      const by = item.sy - (e.isBoss ? 42 : 24);
      ctx.fillStyle = "rgba(0,0,0,0.7)";
      ctx.fillRect(bx - 1, by - 1, bw + 2, bh + 2);
      ctx.fillStyle = e.isBoss ? "#ff9800" : "#ef5350";
      ctx.fillRect(bx, by, bw * Math.max(0, e.hp / e.maxHp), bh);
      ctx.font = "900 10px monospace, sans-serif";
      ctx.fillStyle = "#ffe066";
      ctx.fillText(`Lv.${e.level}`, item.sx, by - 3);
    } else if (item.type === "comp") {
      const comp = item.obj;
      const hop = Math.abs(Math.sin((RUN.time + comp.animOffset) * 9)) * 5;
      const lx = comp.lungeT > 0 ? comp.lungeDx * (comp.lungeT / 0.18) : 0;
      const ly = comp.lungeT > 0 ? comp.lungeDy * (comp.lungeT / 0.18) : 0;
      drawPokemonSprite(ctx, comp.speciesId, item.sx + lx, item.sy + ly, comp.vx, comp.vy, RUN.time * 1.25 + comp.animOffset, 1.55 + comp.evoStage * 0.2, false, "#4fc3f7", hop);
      ctx.font = "900 10px monospace, sans-serif";
      const label = comp.calloutT > 0 ? `💬${comp.calloutText}` : `Lv.${comp.level} ${POKEMON_ZH[comp.speciesId]}`;
      ctx.fillStyle = "#000";
      ctx.fillText(label, item.sx + 1, item.sy - 26 - hop);
      ctx.fillStyle = comp.calloutT > 0 ? "#ffe066" : "#81d4fa";
      ctx.fillText(label, item.sx, item.sy - 27 - hop);
    } else {
      const hop = (Math.abs(RUN.vx) > 0.01 || Math.abs(RUN.vy) > 0.01) ? Math.abs(Math.sin(RUN.time * 10)) * 4 : 0;
      drawPokemonSprite(ctx, RUN.speciesId, item.sx, item.sy, RUN.vx, RUN.vy, RUN.time * 1.25, 1.85 + RUN.evoStage * 0.25, RUN.invulnT > 0.18, "#ffe066", hop);
      const bw = 50;
      const bh = 6;
      const bx = item.sx - bw / 2;
      const by = item.sy + 30;
      ctx.fillStyle = "#1a0d1f";
      ctx.fillRect(bx - 1, by - 1, bw + 2, bh + 2);
      ctx.fillStyle = "#66bb6a";
      ctx.fillRect(bx, by, bw * Math.max(0, RUN.hp / RUN.maxHp), bh);
    }
  }

  // 6. Draw Orbiting Guardian Blades (`vs_bible`)
  for (const o of RUN.orbitals) {
    const sx = (o.x || RUN.x) - camX;
    const sy = (o.y || RUN.y) - camY;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(o.ang + RUN.time * 8);
    ctx.fillStyle = o.color;
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -o.r * 1.25);
    ctx.quadraticCurveTo(o.r * 0.9, 0, 0, o.r * 1.25);
    ctx.quadraticCurveTo(-o.r * 0.9, 0, 0, -o.r * 1.25);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  // 7. Draw Cross Boomerangs (`vs_cross`)
  for (const b of RUN.boomerangs) {
    const sx = b.x - camX;
    const sy = b.y - camY;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(RUN.time * 16);
    ctx.fillStyle = b.color;
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    for (let k = 0; k < 4; k++) {
      ctx.rotate(Math.PI / 2);
      ctx.beginPath();
      ctx.moveTo(0, -b.r * 1.35);
      ctx.lineTo(b.r * 0.38, -b.r * 0.25);
      ctx.lineTo(0, 0);
      ctx.lineTo(-b.r * 0.38, -b.r * 0.25);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
    ctx.restore();
  }

  // 8. Draw Brotato Melee Thrusts/Cleaves & VS Whips (`br_thrust`, `vs_whip`)
  for (const sw of RUN.meleeSwings) {
    if (sw.x1 === undefined) continue;
    const x1 = sw.x1 - camX;
    const y1 = sw.y1 - camY;
    const x2 = sw.x2 - camX;
    const y2 = sw.y2 - camY;
    ctx.save();
    if (sw.kind === "whip") {
      // Vampire Survivors Curved Whip Lash!
      ctx.strokeStyle = sw.color;
      ctx.lineWidth = 8;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      const cx = (x1 + x2) / 2;
      const cy = (y1 + y2) / 2 - 28 * Math.sin((1 - sw.life / sw.maxLife) * Math.PI);
      ctx.quadraticCurveTo(cx, cy, x2, y2);
      ctx.stroke();
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 2.5;
      ctx.stroke();
    } else {
      // Brotato Physical Extending Spear/Claw/Blade Thrust!
      ctx.strokeStyle = "#d7ccc8";
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
      ctx.translate(x2, y2);
      ctx.rotate(sw.curAng || sw.ang);
      ctx.fillStyle = sw.color;
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(16, 0);
      ctx.lineTo(-14, -12);
      ctx.lineTo(-8, 0);
      ctx.lineTo(-14, 12);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
    ctx.restore();
  }

  // 9. Draw Continuous Piercing Lasers (`pk_laser`)
  for (const ls of RUN.lasers) {
    if (ls.x1 === undefined) continue;
    const x1 = ls.x1 - camX;
    const y1 = ls.y1 - camY;
    const x2 = ls.x2 - camX;
    const y2 = ls.y2 - camY;
    ctx.save();
    ctx.strokeStyle = ls.color;
    ctx.lineWidth = ls.wid;
    ctx.lineCap = "round";
    ctx.globalAlpha = 0.65;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = ls.wid * 0.42;
    ctx.globalAlpha = 0.95;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.restore();
  }

  // 10. Draw Projectiles (`runetracer`, `gravity_axe`, `santa_bottle`)
  for (const p of RUN.projectiles) {
    const sx = p.x - camX;
    const sy = p.y - camY;
    ctx.save();
    if (p.kind === "runetracer" && p.trail) {
      for (let t = 0; t < p.trail.length; t++) {
        const pt = p.trail[t];
        ctx.fillStyle = p.color;
        ctx.globalAlpha = ((t + 1) / p.trail.length) * 0.42;
        ctx.beginPath();
        ctx.arc(pt.x - camX, pt.y - camY, p.r * 0.75, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1.0;
    }
    ctx.translate(sx, sy);
    if (p.rot) ctx.rotate(p.rot);
    ctx.fillStyle = p.color;
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    if (p.kind === "gravity_axe") {
      // Heavy jagged rock/hammer!
      ctx.beginPath();
      for (let k = 0; k < 6; k++) {
        const a = (k / 6) * Math.PI * 2;
        const rad = p.r * (k % 2 === 0 ? 1.15 : 0.8);
        if (k === 0) ctx.moveTo(Math.cos(a) * rad, Math.sin(a) * rad);
        else ctx.lineTo(Math.cos(a) * rad, Math.sin(a) * rad);
      }
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.arc(0, 0, p.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
    ctx.restore();
  }

  // 11. Draw Popups
  ctx.textAlign = "center";
  for (const p of RUN.popups) {
    const sx = p.x - camX;
    const sy = p.y - camY;
    ctx.font = `900 ${Math.round(13 * p.scale)}px monospace, sans-serif`;
    ctx.fillStyle = "#000000";
    ctx.fillText(p.text, sx + 1.5, sy + 1.5);
    ctx.fillStyle = p.color;
    ctx.fillText(p.text, sx, sy);
  }

  // 12. Draw 360° Floating Follow Virtual Joystick
  if (JOY.active) {
    ctx.save();
    ctx.strokeStyle = "rgba(255, 224, 102, 0.65)";
    ctx.fillStyle = "rgba(20, 12, 32, 0.35)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(JOY.sx, JOY.sy, JOY.maxR, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // Direction line
    ctx.strokeStyle = "rgba(255, 224, 102, 0.45)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(JOY.sx, JOY.sy);
    ctx.lineTo(JOY.cx, JOY.cy);
    ctx.stroke();

    // Thumb knob
    ctx.fillStyle = "rgba(255, 224, 102, 0.90)";
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(JOY.cx, JOY.cy, 20, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }
}

function loop(now) {
  const dt = Math.min(0.05, (now - lastTime) / 1000);
  lastTime = now;
  updateRun(dt);
  render2D();
  requestAnimationFrame(loop);
}

document.getElementById("btn-start-run").onclick = startRun;
document.getElementById("btn-pause").onclick = pauseRun;
document.getElementById("btn-powerups").onclick = showPowerupsModal;
document.getElementById("btn-evolutions").onclick = showLearnsetModal;
document.getElementById("btn-time-claim").onclick = () => {
  SAVE.gold += 1000;
  writeSave();
  sfx("chest");
  renderMenu();
};
document.getElementById("btn-unlock-all").onclick = () => {
  SAVE.unlockedChars = CHARACTERS.map(c => c.id);
  for (const p of POWERUPS) SAVE.powerups[p.id] = p.max;
  SAVE.gold += 20000;
  writeSave();
  sfx("chest");
  renderMenu();
  alert("已全部解锁：全 9 世代 27 只御三家全开、努力值特训满级！");
};

renderMenu();
requestAnimationFrame(loop);
